```javascript
/**
 * Express router for queue‑related endpoints.
 *
 * This module exposes two read‑only routes that allow consumers to
 * inspect the state of the background job queue.  The data is
 * retrieved via the shared orchestrator instance which aggregates
 * all jobs per server/model.
 *
 * @module routes/queue
 */
import { Router } from 'express';
import { getOrchestratorInstance } from '../orchestrator-instance.js';

const router = Router();

/**
 * GET /api/queue/status
 *
 * Returns the status of **all** jobs (pending, active, completed, failed)
 * grouped by the server/model that owns them.  The response shape matches
 * the structure returned by {@link Orchestrator#getQueueStatus}.
 *
 * @route GET /api/queue/status
 * @returns {Object} JSON response containing the grouped queue status.
 * @example
 * {
 *   "serverA": {
 *     "modelX": {
 *       pending: 3,
 *       active: 1,
 *       completed: 12,
 *       failed: 0
 *     },
 *     "modelY": { ... }
 *   },
 *   "serverB": { ... }
 * }
 */
router.get('/status', function (req, res) {
    const orchestrator = getOrchestratorInstance();
    const status = orchestrator.getQueueStatus();
    res.json(status);
});

/**
 * GET /api/queue/jobs/:jobId
 *
 * Retrieves the status of a specific job identified by `jobId`.  The
 * job information is sourced from the orchestrator’s global job registry
 * (`allJobs`).
 *
 * @route GET /api/queue/jobs/:jobId
 * @param {string} req.params.jobId - The unique identifier of the job.
 * @returns {Object} JSON response containing the job status, e.g.
 *   `{ id, type, state, progress, result, error }`.
 * @throws 404 if the job cannot be found.
 * @example
 * // Successful response
 * {
 *   "id": "12345",
 *   "type": "render",
 *   "state": "completed",
 *   "progress": 100,
 *   "result": { /* job output * / },
 *   "error": null
 * }
 *
 * // Error response
 * 404 Not Found
 * { "error": "Job not found" }
 */
router.get('/jobs/:jobId', function (req, res) {
    const orchestrator = getOrchestratorInstance();
    const job = orchestrator.getJobStatus(req.params.jobId);
    if (!job) {
        res.status(404).json({ error: 'Job not found' });
        return;
    }
    res.json(job);
});

export default router;
```

The added JSDoc comments clearly describe each route’s purpose, parameters, return format, status codes, and example payloads, making the codebase self‑documenting for developers and tools that consume JSDoc.

