import { useEffect, useRef, useState } from 'react';
import { useQuery, useMutation, gql } from '@apollo/client';
import { useNavigate } from 'react-router-dom';
import { Form, Button, Alert, Spinner } from 'react-bootstrap';
import { useForm } from 'react-hook-form';
import { yupResolver } from '@hookform/resolvers/yup';
import * as yup from 'yup';

import { UserProfile, UserProfileUpdateInput, MutationUpdateProfileArgs, Mutation, Query, ProfileUpdateMutation, ProfileQuery } from '../graphql/__generated__/graphql';
import { useIsMounted } from '../hooks/useIsMounted';

const UPDATE_PROFILE = gql`
  mutation ProfileUpdate($input: UserProfileUpdateInput!) {
    profileUpdate(input: $input) {
      id
      name
      email
    }
  }
`;

const GET_PROFILE = gql`
  query Profile {
    me {
      id
      name
      email
    }
  }
`;

const schema = yup.object({
  name: yup.string().required('Name is required'),
  email: yup.string().email('Invalid email').required('Email is required'),
});

type ProfileFormValues = {
  name: string;
  email: string;
};

export const ProfileForm = () => {
  const navigate = useNavigate();
  const isMounted = useIsMounted();

  const {
    data: profileData,
    loading: profileLoading,
    error: profileError,
  } = useQuery<ProfileQuery>(GET_PROFILE);

  const [
    updateProfile,
    { loading: updateLoading, error: updateError, data: updateData },
  ] = useMutation<Mutation, MutationUpdateProfileArgs>(UPDATE_PROFILE);

  const { register, handleSubmit, reset, formState } = useForm<ProfileFormValues>({
    resolver: yupResolver(schema),
  });

  const [formError, setFormError] = useState<string | null>(null);

  useEffect(() => {
    if (profileData?.me) {
      reset({
        name: profileData.me.name ?? '',
        email: profileData.me.email ?? '',
      });
    }
  }, [profileData, reset]);

  useEffect(() => {
    if (isMounted) {
      if (formError) {
        setFormError(null);
      }
    }
  }, [formError, isMounted]);

  useEffect(() => {
    if (updateError && isMounted) {
      setFormError(updateError.message);
    }
  }, [updateError, isMounted]);

  useEffect(() => {
    if (updateData?.profileUpdate && isMounted) {
      navigate('/profile');
    }
  }, [updateData, isMounted, navigate]);

  const onSubmit = handleSubmit(async (data: ProfileFormValues) => {
    try {
      await updateProfile({
        variables: {
          input: {
            name: data.name,
            email: data.email,
          },
        },
      });
    } catch (err) {
      // error handled by useEffect
    }
  });

  if (profileLoading) {
    return <Spinner animation="border" />;
  }

  if (profileError) {
    return <Alert variant="danger">{profileError.message}</Alert>;
  }

  return (
    <Form onSubmit={onSubmit}>
      {formError && <Alert variant="danger">{formError}</Alert>}
      <Form.Group controlId="name" className="mb-3">
        <Form.Label>Name</Form.Label>
        <Form.Control
          type="text"
          isInvalid={!!formState.errors.name}
          {...register('name')}
        />
        <Form.Control.Feedback type="invalid">
          {formState.errors.name?.message}
        </Form.Control.Feedback>
      </Form.Group>

      <Form.Group controlId="email" className="mb-3">
        <Form.Label>Email</Form.Label>
        <Form.Control
          type="email"
          isInvalid={!!formState.errors.email}
          {...register('email')}
        />
        <Form.Control.Feedback type="invalid">
          {formState.errors.email?.message}
        </Form.Control.Feedback>
      </Form.Group>

      <Button type="submit" disabled={updateLoading}>
        {updateLoading ? 'Saving...' : 'Save'}
      </Button>
    </Form>
  );
};

export default ProfileForm;
