import React, { useState, useEffect } from "react";
import {
  useForm,
  FormProvider,
  useFormContext,
  HandleSubmit,
  SubmitHandler,
  RegisterOptions,
} from "react-hook-form";
import { useMutation, useQuery } from "@apollo/client";
import { gql } from "@apollo/client";
import { useToast } from "@chakra-ui/react";

export const UPDATE_PROFILE = gql`
  mutation UpdateProfile($id: ID!, $name: String!, $email: String!, $username: String!) {
    updateProfile(id: $id, name: $name, email: $email, username: $username) {
      id
      name
      email
      username
    }
  }
`;

export const GET_PROFILE = gql`
  query GetProfile($id: ID!) {
    profile(id: $id) {
      id
      name
      email
      username
    }
  }
`;

interface QueryData {
  profile: {
    id: string;
    name: string;
    email: string;
    username: string;
  };
}

interface UpdateProfileVariables {
  id: string;
  name: string;
  email: string;
  username: string;
}

interface UpdateProfileResponse {
  updateProfile: {
    id: string;
    name: string;
    email: string;
    username: string;
  };
}

interface ProfileFormProps {
  id: string;
}

export default function ProfileForm({ id }: ProfileFormProps) {
  const [error, setError] = useState<Error | null>(null);
  const [profile, setProfile] = useState<QueryData["profile"] | null>(null);

  const profileForm = useForm({
    mode: "onChange",
    defaultValues: {
      name: "",
      email: "",
      username: "",
    },
  });

  const {
    handleSubmit,
    register,
    formState: { errors, isValid },
  } = profileForm;

  useQuery<QueryData>(GET_PROFILE, {
    variables: { id },
    onCompleted: (data) => {
      setProfile(data.profile);
      profileForm.setValue("name", data.profile.name ?? "");
      profileForm.setValue("email", data.profile.email ?? "");
      profileForm.setValue("username", data.profile.username ?? "");
    },
    onError: (err) => {
      setError(err as Error);
    },
  });

  const [updateProfile, { loading: mutationLoading }] = useMutation<
    UpdateProfileResponse,
    UpdateProfileVariables
  >(UPDATE_PROFILE, {
    onCompleted: () => {
      setError(null);
    },
    onError: (err) => {
      setError(err as Error);
    },
  });

  const onSubmit: SubmitHandler<UpdateProfileVariables> = async (data) => {
    try {
      await updateProfile({ variables: data });
    } catch (e) {
      // error handled by onError
    }
  };

  const toast = useToast();

  useEffect(() => {
    if (error) {
      toast({
        title: "Error",
        description: error.message,
        status: "error",
        duration: 5000,
        isClosable: true,
      });
    }
  }, [error, toast]);

  return (
    <FormProvider {...profileForm}>
      <form onSubmit={handleSubmit(onSubmit)}>
        <input
          name="name"
          placeholder="Name"
          ref={register({ required: "Name is required" })}
        />
        {errors.name && <p>{errors.name.message}</p>}
        <input
          name="email"
          placeholder="Email"
          ref={register({
            required: "Email is required",
            pattern: {
              value:
                /^[a-zA-Z0-9.!#$%&’*+/=?^_`{|}~-]+@[a-zA-Z0-9-]+(?:\.[a-zA-Z0-9-]+)*$/,
              message: "Invalid email",
            },
          })}
        />
        {errors.email && <p>{errors.email.message}</p>}
        <input
          name="username"
          placeholder="Username"
          ref={register({
            required: "Username is required",
            pattern: {
              value: /^[a-zA-Z0-9]+$/,
              message: "Username can only contain alphanumeric characters",
            },
          })}
        />
        {errors.username && <p>{errors.username.message}</p>}
        <button type="submit" disabled={!isValid || mutationLoading}>
          {mutationLoading ? "Saving..." : "Save"}
        </button>
        {error && <p>{error.message}</p>}
      </form>
    </FormProvider>
  );
}
```

