// ai-server/benchmarking/benchmarkRunner.ts
/**
 * # Benchmark runner utilities
 *
 * This module contains two helpers for executing quality‑benchmark jobs on a
 * model‑server pair.
 *
 * * `runBenchmarksForServer` – legacy, legacy‑compatibility path that first
 *   attempts to run a benchmark through {@link BenchmarkJobExecutor} and,
 *   if that fails, falls back to calling the legacy benchmark functions
 *   directly.  This helper does **not** persist results; it merely aggregates
 *   them in memory.  It is kept for backward‑compatibility but is marked
 *   `@deprecated`; use {@link runBenchmarksWithQueue} or the new queue‑based
 *   executor instead.
 *
 * * `runBenchmarksWithQueue` – the recommended, queue‑aware implementation.
 *   It submits every benchmark type as a `UniversalJob` to the
 *   `BenchmarkJobExecutor`, which internally enqueues it in the
 *   universal queue system.  Results are collected and returned as a
 *   `Record<BenchmarkType, QualityBenchmarkScore>`.
 *
 * Both functions accept the same parameters and return the same shape of
 * result.  The only difference is the execution path: legacy direct call
 * vs. queue‑based execution.
 *
 * ## Notes
 *
 * * The module deliberately imports `BenchmarkJobExecutor` from
 *   `../executors/benchmark-executor.js`; this ensures that all logic
 *   around job creation, retry policies, timeouts, and dependency handling
 *   is centralised in a single place.
 *
 * * Each benchmark job carries a unique `id` constructed from the current
 *   timestamp and a random suffix, so jobs can be tracked in logs or the
 *   queue UI.
 *
 * * The fallback in `runBenchmarksForServer` uses a very permissive timeout
 *   (15 min for execution, 20 min queue) to give the legacy benchmark
 *   functions enough headroom when they are run outside of the queue.
 *
 * * All returned benchmark objects include a `timestamp` field that
 *   records the moment the score was produced (either by the executor
 *   or by the direct call).
 *
 * @module benchmarkRunner
 * @deprecated Prefer {@link BenchmarkJobExecutor} with a queue system for new
 *   implementations.
 */

import { BenchmarkType, QualityBenchmarkScore } from 'shared/types/aiQualityBenchmark.js';
import { BenchmarkJobExecutor } from '../executors/benchmark-executor.js';
import { UniversalJob, JobType } from 'shared/types/universal-job.js';

/**
 * Executes one or more quality benchmarks for a given model/server pair.
 *
 * This is a **legacy** helper.  It first tries to run each benchmark via
 * {@link BenchmarkJobExecutor}.  If that call throws (e.g. the executor
 * cannot be instantiated or the queue is unavailable), it falls back to
 * invoking the legacy benchmark functions directly from `./benchmarks/index.js`.
 *
 * **Return shape** – a `Record` whose keys are the supplied `BenchmarkType`
 * values and whose values are {@link QualityBenchmarkScore} objects that
 * include a `timestamp`.
 *
 * @param modelId - Identifier of the model to benchmark.
 * @param serverId - Identifier of the server on which the model is hosted.
 * @param types - Array of `BenchmarkType` values to run.
 * @returns A promise resolving to a record of benchmark results.
 * @deprecated Use {@link runBenchmarksWithQueue} or the queue‑based
 *   executor for new code.
 */
export async function runBenchmarksForServer(
    modelId: string,
    serverId: string,
    types: readonly BenchmarkType[]
): Promise<Record<BenchmarkType, QualityBenchmarkScore>> {
    console.warn('[benchmarkRunner] runBenchmarksForServer is deprecated. Consider using BenchmarkJobExecutor with queue system.');

    const benchmarks: Record<BenchmarkType, QualityBenchmarkScore> = {} as Record<BenchmarkType, QualityBenchmarkScore>;
    const executor = new BenchmarkJobExecutor();

    for (const type of types) {
        let score = 0;
        let rubric = '';
        const timestamp = new Date().toISOString();

        try {
            // Build a job that the executor will place into the queue.
            const job: UniversalJob = {
                id: `legacy-benchmark-${Date.now()}-${Math.random().toString(36).substr(2, 9)}`,
                type: JobType.QUALITY_BENCHMARK,
                category: 'benchmark' as any,
                modelId,
                payload: {
                    modelId,
                    benchmarkType: type,
                    prompt: 'Default benchmark prompt for legacy compatibility'
                },
                priority: 'normal' as any,
                dependencies: [],
                constraints: {
                    serverAffinity: serverId,
                    requiresModel: modelId,
                    canSteal: false,
                    stealable: false
                },
                metadata: {
                    submittedAt: new Date(),
                    tags: [type, 'legacy'],
                    correlationId: `legacy-benchmark-${type}`
                },
                timeout: {
                    executionTimeoutMs: 15 * 60 * 1000, // 15 min CPU inference
                    queueTimeoutMs: 20 * 60 * 1000
                },
                retryPolicy: {
                    maxRetries: 3,
                    retryDelayMs: 1000,
                    exponentialBackoff: true
                }
            };

            const result = await executor.execute(job);

            if (result.success && result.result) {
                score = result.result.score ?? 0;
                rubric = result.result.rubric ?? '';
            } else {
                rubric = result.error ?? 'Unknown error occurred';
            }
        } catch (err) {
            // Fallback to direct benchmark function when queue‑based execution fails.
            console.warn(`Queue-based execution failed for ${type}, falling back to direct call:`, err);

            try {
                const functionName = type
                    .split('-')
                    .map((part, index) =>
                        index === 0
                            ? `evaluate${part.charAt(0).toUpperCase() + part.slice(1)}`
                            : `${part.charAt(0).toUpperCase() + part.slice(1)}`
                    )
                    .join('');

                const benchmarkModule = await import('./benchmarks/index.js');
                const fn = (benchmarkModule as any)[functionName];

                if (typeof fn === 'function') {
                    const result = await fn(modelId, serverId, 15 * 60 * 1000);
                    score = result.score ?? 0;
                    rubric = result.rubric ?? '';
                } else {
                    rubric = `Unknown benchmark function: ${functionName}`;
                }
            } catch (directErr) {
                rubric = `Error: ${(directErr instanceof Error ? directErr.message : String(directErr))}`;
            }
        }

        benchmarks[type] = { type, score, rubric, timestamp };
    }

    return benchmarks;
}

/**
 * Queue‑aware benchmark runner that integrates with the universal queue
 * system.  Each requested benchmark type is wrapped into a
 * {@link UniversalJob} and submitted to {@link BenchmarkJobExecutor}.
 *
 * This is the **recommended** way to run benchmarks in production.  All
 * jobs are subject to the executor’s retry policy, timeout configuration,
 * and queue prioritisation.
 *
 * **Return shape** – same as {@link runBenchmarksForServer}: a record of
 * `BenchmarkType` keys mapped to {@link QualityBenchmarkScore} values
 * (including a `timestamp`).
 *
 * @param modelId - Identifier of the model to benchmark.
 * @param serverId - Identifier of the server that hosts the model.
 * @param types - Array of `BenchmarkType` values to run.
 * @returns A promise resolving to a record of benchmark results.
 */
export async function runBenchmarksWithQueue(
    modelId: string,
    serverId: string,
    types: readonly BenchmarkType[]
): Promise<Record<BenchmarkType, QualityBenchmarkScore>> {
    const executor = new BenchmarkJobExecutor();
    const results: Record<BenchmarkType, QualityBenchmarkScore> = {} as Record<BenchmarkType, QualityBenchmarkScore>;

    for (const benchmarkType of types) {
        const job: UniversalJob = {
            id: `queue-benchmark-${Date.now()}-${Math.random().toString(36).substr(2, 9)}`,
            type: JobType.QUALITY_BENCHMARK,
            category: 'benchmark' as any,
            modelId,
            payload: {
                modelId,
                benchmarkType,
                prompt: 'Queue-based benchmark execution'
            },
            priority: 'normal' as any,
            dependencies: [],
            constraints: {
                serverAffinity: serverId,
                requiresModel: modelId,
                canSteal: false,
                stealable: false
            },
            metadata: {
                submittedAt: new Date(),
                tags: [benchmarkType, 'queue-based'],
                correlationId: `queue-benchmark-${benchmarkType}`
            },
            timeout: {
                executionTimeoutMs: 30_000, // 30 s CPU inference
                queueTimeoutMs: 60_000
            },
            retryPolicy: {
                maxRetries: 3,
                retryDelayMs: 1_000,
                exponentialBackoff: true
            }
        };

        const result = await executor.execute(job);

        if (result.success && result.result) {
            results[benchmarkType] = result.result;
        } else {
            results[benchmarkType] = {
                type: benchmarkType,
                score: 0,
                rubric: result.error ?? 'Execution failed',
                timestamp: new Date().toISOString()
            };
        }
    }

    return results;
}
