 * test should run. It does not affect the scoring logic.
 *
 * @property {string} suiteType - The type of benchmark; 'quality' indicates a
 *   purely qualitative test (no gating dependencies).
 * @property {string[]} requires - A list of other benchmark IDs that must
 *   succeed before this one is executed.
 */
export const characterConsistencyBenchmarkMeta = {
    suiteType: 'quality',
    requires: []
};

/**
 * Character Consistency Benchmark
 *
 * Evaluates the model's ability to maintain a character’s traits, personality
 * and mannerisms across multiple scenes that occur in different contexts.
 *
 * The evaluation works in three stages:
 *   1. **Trait consistency** – checks for methodical behaviour, compassion/
 *      decisiveness balance, finger‑tapping mannerism, engineering jargon
 *      and name consistency.
 *   2. **Scene structure** – ensures that the model generates at least two
 *      distinct scenes and switches appropriately between a command context
 *      and a casual one.
 *   3. **Quality & diversity** – rewards longer, higher‑BLEU/ROUGE responses
 *      while penalising repetitive text or missing character references.
 *
 * The final score is bounded in the range [0, 1] and is returned as a
 * `Promise<number>`.
 *
 * @async
 * @function evaluateCharacterConsistency
 * @param {string} modelId - Identifier of the model under test.
 * @param {string} serverId - Identifier of the server that will receive the
 *   request.
 * @param {number} [timeoutMs=5*60*1000] - Maximum time in milliseconds the
 *   model is allowed to take. Defaults to 5 minutes.
 * @param {string} [prompt] - Optional prompt to override the default
 *   character scenario. When omitted, the hard‑coded scenario is used.
 * @returns {Promise<number>} A promise that resolves to the benchmark score
 *   (0 ≤ score ≤ 1). In case of a runtime error the function logs the issue
 *   and returns the lowest valid score (0.1).
 *
 * @example
 * // Basic usage
 * const score = await evaluateCharacterConsistency('gpt-4', 'prod-1');
 * console.log(`Character consistency score: ${score.toFixed(2)}`);
 *
 * @example
 * // With a custom prompt
 * const customPrompt = `Write a scene where Captain Elena ...`;
 * const score = await evaluateCharacterConsistency('gpt-4', 'prod-1', 300000, customPrompt);
 *
 * @throws {Error} If the model API call fails; the error is caught and logged,
 *   and the function resolves to 0.1 instead of throwing.
 *
 * @see {@link callModelAPI} - Utility for invoking the model endpoint.
 * @see {@link safeBleu} {@link safeRouge} - Scoring helpers.
 * @see {@link logger} - Logging facility used for warnings.
 */
export async function evaluateCharacterConsistency(
    modelId: string,
    serverId: string,
    timeoutMs = 5 * 60 * 1000,
    prompt?: string
): Promise<number> {
    // Default prompt describing Captain Elena Vasquez
    const defaultPrompt = [
        'You are writing a chapter featuring Captain Elena Vasquez, a 42-year-old former engineer turned starship captain.',
        'She is known for being methodical, compassionate but decisive, and has a habit of tapping her fingers when thinking.',
        'She also speaks with slight technical jargon due to her engineering background.',
        '',
        'Write two scenes: First, Elena making a difficult command decision about whether to help a stranded alien ship.',
        'Second, Elena having a casual conversation with her crew in the mess hall.',
        '',
        'Ensure her personality, speech patterns, and mannerisms remain consistent between both scenes.'
    ].join(' ');

    const usedPrompt = prompt ?? defaultPrompt;
    let score = 0.2; // Base score

    try {
        const response = await callModelAPI(serverId, modelId, usedPrompt, 3, 500, timeoutMs);
        const text = typeof response === 'string' ? response.trim() : '';

        // ---- Trait consistency scoring ----
        let traitScore = 0;

        // Methodical behaviour
        if (/analyz|consider|evaluat|assess|methodical|systematic|step/i.test(text)) {
            traitScore += 0.15;
        }

        // Compassion + decisiveness balance
        if (/compassion|care|help|concern/i.test(text) && /decision|command|order|decisive/i.test(text)) {
            traitScore += 0.15;
        }

        // Finger‑tapping mannerism
        if (/tap|finger|drum|nervous|thinking/i.test(text)) {
            traitScore += 0.1;
        }

        // Engineering jargon
        if (/system|engineer|technical|protocol|parameters|configuration|diagnostic/i.test(text)) {
            traitScore += 0.1;
        }

        // Name consistency
        const elenaMatches = (text.match(/elena|vasquez|captain/gi) || []).length;
        if (elenaMatches >= 3) {
            traitScore += 0.05;
        }

        // ---- Scene structure scoring ----
        let structureScore = 0;
        const scenes = text.split(/scene|chapter/i).filter(s => s.trim().length > 50);

        if (scenes.length >= 2) {
            structureScore += 0.1;
        }

        // Context switch (command vs casual)
        if (/command|bridge|decision|alien/i.test(text) && /mess hall|casual|crew|conversation/i.test(text)) {
            structureScore += 0.1;
        }

        // ---- BLEU / ROUGE scoring ----
        const reference = 'Captain Elena Vasquez methodically considered the decision, tapping her fingers on the console. Her engineering background showed in her systematic approach to command situations.';
        let bleuScore = 0;
        let rougeScore = 0;

        try {
            bleuScore = safeBleu(text, [reference]);
            rougeScore = safeRouge(text, reference);
        } catch (err) {
            logger.warn('Character consistency BLEU/ROUGE error: ' + (err instanceof Error ? err.message : String(err)));
        }

        // ---- Length & quality checks ----
        let qualityScore = 0;
        if (text.length > 500) qualityScore += 0.05;
        if (text.length > 1000) qualityScore += 0.05;

        // Penalise missing or inconsistent name
        if (elenaMatches < 2) {
            traitScore = Math.min(traitScore, 0.1);
        }

        // Penalise low lexical diversity
        const uniqueWords = new Set(text.toLowerCase().split(/\s+/)).size;
        const totalWords = text.split(/\s+/).length;
        const diversity = totalWords > 0 ? uniqueWords / totalWords : 0;

        if (diversity < 0.3) {
            qualityScore = Math.min(qualityScore, 0.05);
        }

        // Final score aggregation
        score += traitScore + structureScore + qualityScore + (0.1 * bleuScore) + (0.1 * rougeScore);

    } catch (err) {
        logger.warn('Character consistency evaluation error: ' + (err instanceof Error ? err.message : String(err)));
        return 0.1;
    }

    // Clamp to [0, 1]
    return Math.max(0, Math.min(score, 1.0));
}
```

