export const DEFAULT_PROMPT = `Write a short conversation between a Starfleet captain and a Romulan ambassador negotiating a ceasefire. 
Each line should be a new speaker, labeled with their role. Use realistic, in‑universe dialogue and negotiation tactics.`;

