  MIN_LINES: 4,
  MAX_LINES: 12,
  MIN_SPEAKERS: 2,
  PENALTY: 0.05,
};

export const PATTERNS = {
  SPEAKER: /^(Captain|Romulan|Ambassador|Commander|[A-Za-z]+):/i,
  NEGOTIATION: /ceasefire|peace|agreement|terms|negotiat|treaty|hostilities|diplomacy/i,
