// apiClient.ts
import { logger } from "./logger"; // whatever logger you prefer

export interface PostResult {
  ok: boolean;
  status: number;
  json?: any;
  body?: string;   // the request payload (for debugging)
}

export async function postJSON(
  url: string,
  body: unknown,
  timeoutMs: number,
): Promise<PostResult> {
  const controller = new AbortController();
  const signal = controller.signal;

  const timeout = setTimeout(() => controller.abort(), timeoutMs);

  try {
    const res = await fetch(url, {
      method: "POST",
      headers: { "Content-Type": "application/json" },
      body: JSON.stringify(body),
      signal,
    });

    const json = await res.json().catch(() => undefined);
    return { ok: res.ok, status: res.status, json, body: JSON.stringify(body) };
  } catch (err: unknown) {
    logger.error(`fetchJSON("${url}") error`, err);
    throw err;
  } finally {
    clearTimeout(timeout);
  }
}
```

