// utils.ts
import { performance } from "perf_hooks";
import { clamp } from "lodash-es";
import { logger } from "./logger";

export function clampScore(v: number): number {
  return clamp(v, 0, 1);
}

export function timeIt<T>(fn: () => Promise<T>): Promise<{ elapsedMs: number; result: T }> {
  const start = performance.now();
  return fn().then((res) => ({
    elapsedMs: performance.now() - start,
    result: res,
  }));
}

export class RubricBuilder {
  private lines: string[] = [];

  push(line: string): this {
    this.lines.push(line);
    return this;
  }

  /**
   * @param finalScore  the numeric score that will be printed as “Final score”
   * @param finalWeight  multiplier applied to the raw score before clamping
   */
  finalize(finalScore: number, finalWeight = 1): string {
    const weight = finalWeight;
    const weighted = clampScore(finalScore * weight);
    this.push(`Final score: ${weighted.toFixed(2)}`);
    return this.lines.join("\n");
  }
}

export function handleError(operation: string, err: unknown): never {
  logger.error(`${operation} failed`, err);
  // Throwing preserves the stack‑trace for callers that want to bubble it up
  throw new Error(`${operation} failed: ${String(err)}`);
}
