## 3️⃣ `metrics.ts`

```ts
// metrics.ts
export interface EmbeddingMetrics {
  /** average cosine similarity between reference‑vector pairs */
  similarity?: number;

  /** overall request latency (ms) */
  latency?: number;

  /** coefficient of variation of per‑pair similarities */
  cv?: number;
}

export function calcStdDev(values: number[]): number {
  const mean = values.reduce((a, b) => a + b, 0) / values.length;
  const sq = values.map((v) => (v - mean) ** 2);
  const variance = sq.reduce((a, b) => a + b, 0) / values.length;
  return Math.sqrt(variance);
}

export function calcCV(values: number[]): number {
  const mean = values.reduce((a, b) => a + b, 0) / values.length;
  return mean === 0 ? 0 : calcStdDev(values) / mean;
}

/**
 * Cosine similarity between two vectors.
 * All vectors are assumed to be normalised.
 */
export function cosineSimilarity(a: number[], b: number[]): number {
  let dot = 0;
  for (let i = 0; i < a.length; i++) dot += a[i] * b[i];
  return dot; // because the vectors are already normalised
}

/**
 * Average cosine similarity for a collection of *paired* vectors.
 * `pairs` is an array of `[vectorA, vectorB]` tuples.
 */
export function averageSimilarity(pairs: [number[], number[]][]): number {
  if (pairs.length === 0) return 0;
  const sims = pairs.map(([a, b]) => cosineSimilarity(a, b));
  return sims.reduce((a, b) => a + b, 0) / sims.length;
}
```

