// utils.ts (more helpers)
import { EMBEDDING_TEST_TEXTS, DETECT } from "./constants";
import { postJSON } from "./apiClient";
import { DetectionResult } from "./embeddings";

export async function fetchWithTimeout(
  url: string,
  body: unknown,
  timeoutMs: number,
): Promise<Response> {
  const controller = new AbortController();
  const timeout = setTimeout(() => controller.abort(), timeoutMs);

  try {
    const res = await fetch(url, {
      method: "POST",
      headers: { "Content-Type": "application/json" },
      body: JSON.stringify(body),
      signal: controller.signal,
    });
    return res;
  } finally {
    clearTimeout(timeout);
  }
}

/**
 * Runs an async callback and returns how long it took in **ms**.
 */
export async function measure<T>(cb: () => Promise<T>): Promise<{ ms: number; value: T }> {
  const start = performance.now();
  const value = await cb();
  const ms = performance.now() - start;
  return { ms, value };
}

/**
 * Common scoring rule for a category
 */
export function scoreFromWeight(
  category: string,
  raw: number,
  rubric: RubricBuilder,
  weight = 1,
): number {
  const score = clampScore(raw * weight);
  rubric.push(`${category} (weight=${weight}): ${score.toFixed(2)}`);
  return score;
}
