// embeddings.ts
import { logger } from "./logger";
import { Config, ConfigProvider } from "./constants";
import { postJSON } from "./apiClient";
import { RubricBuilder, clampScore, handleError } from "./utils";
import {
  EmbeddingMetrics,
  averageSimilarity,
  calcCV,
  calcStdDev,
  cosineSimilarity,
} from "./metrics";
import { BenchmarkType } from "./types";

/**
 * Score a raw numeric value into a normalised 0‑1 score.
 */
export function normalizeScore(v: number): number {
  return Math.max(0, Math.min(1, v));
}

/**
 * Builds a standard benchmark result.
 */
export function buildResult(
  type: BenchmarkType,
  rawScore: number,
  rubricLines: string[],
  weight = 1,
  metrics?: EmbeddingMetrics,
): BenchmarkResult {
  const finalScore = normalizeScore(rawScore * weight);
  const rubric = rubricLines.join("\n");
  return { type, score: finalScore, rubric, metrics, timestamp: new Date().toISOString() };
}
