### 5️⃣.1️⃣ `evaluateEmbeddingQuality`

```ts
export async function evaluateEmbeddingQuality(
  config: Partial<Config> = {},
): Promise<BenchmarkResult> {
  const { qualityTimeoutMs, qualityTestPairs } = ConfigProvider.merge(config);

  const rubric = new RubricBuilder();
  const similarities: [number[], number[]][] = []; // will be filled with vector pairs
  const timings: number[] = []; // request latencies

  for (let i = 0; i < qualityTestPairs; i++) {
    const refPrompt = EMBEDDING_TEST_TEXTS[i];
    const testPrompt = EMBEDDING_TEST_TEXTS[i + 1] ?? `random${Date.now()}`;

    // two async calls that run in parallel
    const [refResp, testResp] = await Promise.all([
      measure(() => postJSON("/embedding", { prompt: refPrompt }, qualityTimeoutMs)),
      measure(() => postJSON("/embedding", { prompt: testPrompt }, qualityTimeoutMs)),
    ]);

    // 1️⃣ record rubric lines
    rubric.push(`Embedding request #${i + 1} – latency: ${refResp.elapsedMs.toFixed(1)} ms`);
    rubric.push(`Test request #${i + 1} – latency: ${testResp.elapsedMs.toFixed(1)} ms`);

    // 2️⃣ store similarity
    const pair = [refResp.result as number[], testResp.result as number[]];
    similarities.push(pair);

    // 3️⃣ keep raw latency to compute CV
    timings.push(refResp.elapsedMs);
  }

  // ----- compute metrics -----
  const similarityScore = averageSimilarity(similarities);
  rubric.push(`Overall similarity: ${similarityScore.toFixed(3)}`);

  const cv = calcCV(similarities.map(([a, b]) => cosineSimilarity(a, b)));
  rubric.push(`Coefficient of Variation: ${cv.toFixed(3)}`);

  // ----- build final result -----
  const rawScore = similarityScore * (1 - cv); // weight similarity by 1 - CV
  const metrics: EmbeddingMetrics = { similarity: similarityScore, cv };

  return buildResult(BenchmarkType.QUALITY, rawScore, rubric.toLines(), 1, metrics);
}
```

