### 5️⃣.2️⃣ `evaluateEmbeddingSpeed`

```ts
export async function evaluateEmbeddingSpeed(
  config: Partial<Config> = {},
): Promise<BenchmarkResult> {
  const { speedTimeoutMs, speedTestPairs } = ConfigProvider.merge(config);

  const rubric = new RubricBuilder();
  const latencies: number[] = [];

  for (let i = 0; i < speedTestPairs; i++) {
    const prompt = EMBEDDING_TEST_TEXTS[i];

    const { ms, value } = await measure(() =>
      postJSON("/embedding", { prompt }, speedTimeoutMs),
    );

    latencies.push(ms);
    rubric.push(`Request #${i + 1} – latency: ${ms.toFixed(1)} ms`);
  }

  const meanLatency = latencies.reduce((a, b) => a + b, 0) / latencies.length;
  rubric.push(`Average latency: ${meanLatency.toFixed(1)} ms`);

  // Score: fast < FAST → 1, medium < MEDIUM → 0.5, slow → 0
  const rawScore =
    meanLatency < SPEED_THRESHOLDS.FAST ? 1
    : meanLatency < SPEED_THRESHOLDS.MEDIUM ? 0.5
    : 0;

  const metrics: EmbeddingMetrics = { latency: meanLatency };

  return buildResult(BenchmarkType.SPEED, rawScore, rubric.toLines(), 1, metrics);
}
```

