```ts
export async function detectEmbeddingQuality(
  config: Partial<Config> = {},
): Promise<BenchmarkResult> {
  const { detectionTimeoutMs } = ConfigProvider.merge(config);

  const rubric = new RubricBuilder();

  try {
    const res = await postJSON("/detect", { prompt: "some prompt" }, detectionTimeoutMs);
    rubric.push(`Detection request – status: ${res.status}`);
    rubric.push(`Body: ${res.body}`);

    const score = res.status === DETECT.EXPECTED_STATUS_400 ? 1 : 0;
    rubric.finalize(score);

    return buildResult(BenchmarkType.DETECTION, score, rubric.toLines(), 1);
  } catch (e) {
    return handleError("detectEmbeddingQuality", e);
  }
}
```

