 *   * **Scoring** – The raw score is the sum of weighted checks, then clipped
 *     to the `[0, 1]` range.
 *   * **Use‑case** – Call from a test harness or CI pipeline to keep an
 *     eye on creative writing quality over time.
 *
 * @module benchmarks/evaluateCreativeWriting
 * @version 1.0.0
 */

import { callModelAPI, safeBleu, safeRouge } from '../benchmarkUtils.js';
import { logger } from 'shared/logging/logger.js';

/**
 * @typedef {Object} BenchmarkMetadata
 * @property {string} suiteType  - Type of benchmark (always `'quality'` for this suite).
 * @property {string[]} requires - Array of gating dependencies; empty for this benchmark.
 */

/**
 * Metadata for the creative‑writing benchmark.
 *
 * @type {BenchmarkMetadata}
 */
export const creativeWritingBenchmarkMeta = {
  suiteType: 'quality',
  requires: []
};

/**
 * Evaluates a model’s creative‑writing capability.
 *
 * The function sends a prompt to the model, receives the generated text,
 * and calculates a score between 0 and 1 based on:
 *   * **Length** – bonus for 50‑plus and 150‑plus characters.
 *   * **Topic relevance** – keyword checks for Starfleet‑related terms.
 *   * **Narrative structure** – presence of temporal words and multiple
 *     sentences.
 *   * **Similarity to reference** – combined BLEU & ROUGE scores.
 *
 * @param {string} modelId      - Identifier of the model to benchmark.
 * @param {string} serverId     - Identifier of the server hosting the model.
 * @param {number} [timeoutMs=300000] - Request timeout in milliseconds (default 5 min).
 * @param {string} [prompt]     - Optional custom prompt; a default Starfleet prompt is used when omitted.
 * @returns {Promise<number>}   - Promise that resolves to a score in the range [0, 1].
 *
 * @throws {Error} If `callModelAPI` throws; the error is logged and the function
 *                 continues, returning 0.
 */
export async function evaluateCreativeWriting(
  modelId: string,
  serverId: string,
  timeoutMs: number = 5 * 60 * 1000,
  prompt?: string
): Promise<number> {
  const defaultPrompt =
    'Write a creative backstory for a new Starfleet officer. Include their background, motivations, and a defining moment in their career.';
  const usedPrompt = prompt ?? defaultPrompt;
  const reference =
    'Commander Sarah Chen, a brilliant tactical officer with experience in deep space exploration, joined Starfleet after witnessing the destruction of her home colony and dedicated her life to protecting others.';
  let score = 0;

  try {
    const response = await callModelAPI(serverId, modelId, usedPrompt, 3, 500, timeoutMs);

    /* Basic quality checks */
    if (response.length > 50) score += 0.2;
    if (response.length > 150) score += 0.2;

    /* Content relevance checks */
    if (/officer|starfleet|command|captain|lieutenant/i.test(response)) score += 0.15;
    if (/background|motivation|career|experience/i.test(response)) score += 0.15;

    /* Narrative quality indicators */
    if (/after|before|when|during|while/i.test(response)) score += 0.1; // Temporal connections
    if (response.split('.').length > 2) score += 0.1; // Multiple sentences

    /* BLEU/ROUGE comparison with reference */
    const bleuScore = safeBleu(response, [reference]);
    const rougeScore = safeRouge(response, reference);
    score += (bleuScore + rougeScore) * 0.1;
  } catch (err) {
    logger.warn(
      'Creative writing error: ' + (err instanceof Error ? err.message : String(err))
    );
  }

  return Math.max(0, Math.min(score, 1.0));
}
