```ts
/**
 * @file benchmarks/evaluateJSONAssembly.ts
 * @module benchmarks/evaluateJSONAssembly
 * @description
 *   A lightweight quality‑benchmark that evaluates a model’s ability to
 *   generate a **well‑structured JSON object**.  
 *   The benchmark sends a prompt to a language model, parses the response
 *   as JSON, validates it against a strict schema, and awards points
 *   for both syntactic correctness and content quality.
 *
 *   The function returns a score in the range **0 – 1** where:
 *   - `0.5` → perfectly valid JSON matching the schema
 *   - up to `0.2` extra points if the `name` field is non‑empty
 *   - up to `0.15` points for a non‑empty `rank`
 *   - up to `0.15` points for a `backstory` longer than 10 characters
 *   - `0.1` partial credit if the response looks like JSON but fails validation
 *   - `0.05` minimal credit on recoverable errors
 *
 *   Any score outside 0–1 is clamped back to that range.
 *
 * @version 1.0.0
 */

/* --------------------------------------------------------------------- */
/*  Metadata used by the gating / scheduling framework                   */
/* --------------------------------------------------------------------- */

/**
 * Benchmark metadata for gating and scheduling.
 *
 * @type {Object}
 * @property {string} suiteType  - The type of benchmark; `'quality'` indicates
 *                                 a purely evaluative (non‑performance) test.
 * @property {Array<string>} requires - List of prerequisite benchmark keys;
 *                                   empty array means no dependencies.
 */
export const jsonAssemblyBenchmarkMeta = {
    suiteType: 'quality',
    requires: []
};

/* --------------------------------------------------------------------- */
/*  Dependencies                                                   */
/* --------------------------------------------------------------------- */

import Ajv from 'ajv';
import { callModelAPI } from '../benchmarkUtils.js';
import { logger } from 'shared/logging/logger.js';

const ajv = new Ajv.default();

/* --------------------------------------------------------------------- */
/*  Public API                                                      */
/* --------------------------------------------------------------------- */

/**
 * Evaluates a language model’s ability to generate a correctly‑structured
 * JSON object.
 *
 * @param {string} modelId   - Identifier of the model under test.
 * @param {string} serverId  - Identifier of the server hosting the model.
 * @param {number} [timeoutMs=5*60*1000] - Request timeout in milliseconds
 *                                        (default 5 minutes).
 * @param {string} [prompt]  - Custom prompt to send to the model.  If omitted,
 *                            a default Star‑Trek character prompt is used.
 * @returns {Promise<number>}  - Normalized score in the range `[0, 1]`.
 *
 * @example
 * const score = await evaluateJSONAssembly('gpt-4', 'server-01');
 * console.log(`JSON assembly score: ${score}`);
 *
 * @throws {Error} If the model request fails after the timeout.
 */
export async function evaluateJSONAssembly(
    modelId: string,
    serverId: string,
    timeoutMs: number = 5 * 60 * 1000,
    prompt?: string
): Promise<number> {
    // ------------------------------------------------------------------
    //  1. Setup: prompt & reference JSON
    // ------------------------------------------------------------------
    const defaultPrompt = 'Generate a JSON object for a Star Trek character with name, rank, and backstory. Return only the JSON object.';
    const usedPrompt = prompt ?? defaultPrompt;
    const reference = '{"name": "Jean-Luc Picard", "rank": "Captain", "backstory": "Experienced Starfleet officer"}';

    // ------------------------------------------------------------------
    //  2. Schema definition (used by Ajv for validation)
    // ------------------------------------------------------------------
    const schema = {
        type: 'object',
        required: ['name', 'rank', 'backstory'],
        properties: {
            name:    { type: 'string' },
            rank:    { type: 'string' },
            backstory: { type: 'string' }
        }
    };

    let score = 0;

    try {
        // ------------------------------------------------------------------
        //  3. Call the model API
        // ------------------------------------------------------------------
        const response = await callModelAPI(serverId, modelId, usedPrompt, 3, 500, timeoutMs);

        // ------------------------------------------------------------------
        //  4. Extract JSON substring from the model’s raw reply
        // ------------------------------------------------------------------
        let jsonStr = response.trim();
        const jsonMatch = jsonStr.match(/\{.*\}/s);
        if (jsonMatch) {
            jsonStr = jsonMatch[0];
        }

        const parsedResponse = JSON.parse(jsonStr);

        // ------------------------------------------------------------------
        //  5. Validate JSON structure and compute score
        // ------------------------------------------------------------------
        const isValid = ajv.validate(schema, parsedResponse);
        if (isValid) {
            score += 0.5; // Base score for a structurally valid JSON object

            // Content‑quality bonuses
            if (parsedResponse.name && parsedResponse.name.length > 0) score += 0.2;
            if (parsedResponse.rank && parsedResponse.rank.length > 0) score += 0.15;
            if (parsedResponse.backstory && parsedResponse.backstory.length > 10) score += 0.15;
        } else {
            // Partial credit if the reply still looks like JSON
            if (jsonStr.startsWith('{') && jsonStr.endsWith('}')) score += 0.1;
        }
    } catch (err) {
        // ------------------------------------------------------------------
        //  6. Error handling – log and apply minimal credit if possible
        // ------------------------------------------------------------------
        logger.warn('JSON assembly error: ' + (err instanceof Error ? err.message : String(err)));

        if (typeof err === 'string' && err.includes('{')) {
            score = 0.05;
        }
    }

    // Clamp the score to the 0‑1 range before returning
    return Math.max(0, Math.min(score, 1.0));
}
