/**
 * Benchmarks / evaluateTaskPlanning.ts
 *
 * This module evaluates a model’s ability to produce a structured task plan.
 *
 * @module benchmarks/evaluateTaskPlanning
 * @version 1.0.0
 */

import { callModelAPI } from '../benchmarkUtils.js';
import { logger } from 'shared/logging/logger.js';

/* --------------------------------------------------------------------------- */
/*  CONFIGURATION                                                             */
/* --------------------------------------------------------------------------- */

/**
 * Default request timeout: 5 minutes.
 */
export const TIMEOUT_MS = 5 * 60 * 1000;

/**
 * Default prompt that is used when no custom prompt is supplied.
 */
export const DEFAULT_PROMPT =
  'Plan a diplomatic mission to the Romulan Neutral Zone. ' +
  'Break down the mission into logical steps including preparation, execution, ' +
  'and follow‑up phases.';

/**
 * The reference answer used only for documentation purposes.
 */
export const REFERENCE_ANSWER =
  'Establish contact, negotiate terms, ensure security, report to Starfleet.';

/**
 * Scoring weights.  All keys are case‑insensitive regexes.
 * The values are the weight that is added when the pattern matches.
 */
export const SCORE_WEIGHTS = {
  /** Structured numbering or bullets */
  '((\\d\\.)|step \\d|phase \\d|\\d\\))': 0.2,
  '([•\\-*])': 0.2,
  '((step|phase|stage|first|second|then|next|finally)\\b)': 0.2,

  /** Content relevance */
  '(contact|communicat|reach out)': 0.15,
  '(negotiat|discuss|terms|agreement)': 0.15,
  '(security|safe|protect|guard)': 0.1,
  '(report|debrief|inform|update)': 0.1,

  /** Quality indicators */
  '^.{101,}': 0.1,                // > 100 chars
  '(\\.|\\!|\\?)': 0.1,           // multiple sentences
};

/**
 * Interface for optional arguments to {@link evaluateTaskPlanning}.
 */
export interface EvaluateOptions {
  /** Request timeout in milliseconds. */
  timeoutMs?: number;
  /** Custom prompt. If omitted, {@link DEFAULT_PROMPT} is used. */
  prompt?: string;
}

/* --------------------------------------------------------------------------- */
/*  PURE SCORING LOGIC                                                        */
/* --------------------------------------------------------------------------- */

/**
 * Score a raw response string according to the rules in {@link SCORE_WEIGHTS}.
 *
 * @param text – Raw text returned by the model
 * @returns A value in the range [0, 1]
 */
export function scoreResponse(text: string): number {
  let score = 0;

  for (const [pattern, weight] of Object.entries(SCORE_WEIGHTS)) {
    const regex = new RegExp(pattern, 'i');
    if (regex.test(text)) {
      score += weight;
    }
  }

  // Clamp to [0, 1]
  return Math.max(0, Math.min(score, 1));
}

/* --------------------------------------------------------------------------- */
/*  PUBLIC API                                                              */
/* --------------------------------------------------------------------------- */

/**
 * Evaluate a model’s task‑planning capabilities.
 *
 * @param modelId   – Identifier of the model to benchmark
 * @param serverId  – Identifier of the hosting server
 * @param options   – Optional request configuration
 * @returns A promise that resolves to a score in the range [0, 1]
 */
export async function evaluateTaskPlanning(
  modelId: string,
  serverId: string,
  options: EvaluateOptions = {}
): Promise<number> {
  const { timeoutMs = TIMEOUT_MS, prompt = DEFAULT_PROMPT } = options;

  try {
    const response = await callModelAPI(
      serverId,
      modelId,
      prompt,
      3,     // temperature
      500,   // maxTokens
      timeoutMs
    );

    // Guard against a missing or empty response
    if (!response || typeof response !== 'string') {
      logger.warn(`evaluateTaskPlanning: empty response for model ${modelId}`);
      return 0;
    }

    return scoreResponse(response);
  } catch (err) {
    // Preserve the original stack trace
    logger.warn(`Task planning error: ${err instanceof Error ? err.message : err}`);
    return 0;
  }
}

/* --------------------------------------------------------------------------- */
/*  METADATA (kept separate for clarity, but could live in its own file)    */
/* --------------------------------------------------------------------------- */

export const taskPlanningBenchmarkMeta = {
  suiteType: 'quality' as const,
  requires: [] as const,
};
```

### What changed and why?

| Change | Benefit |
|--------|---------|
| **Single source of truth for constants** (`TIMEOUT_MS`, `DEFAULT_PROMPT`, `SCORE_WEIGHTS`) | Easy to tweak, better readability, prevents accidental duplication. |
| **`SCORE_WEIGHTS` as a map** | Eliminates repeated regex checks, makes it trivial to add/remove scoring rules. |
| **Pure `scoreResponse` function** | Testable in isolation, no side‑effects, no external dependencies. |
| **`EvaluateOptions` interface** | Enforces shape of options, makes the function signature explicit. |
| **Graceful handling of empty responses** | Avoids `undefined` or `NaN` scores. |
| **Error handling uses template literals & passes original error** | Keeps stack trace and provides consistent log format. |
| **Removed unused imports** | Keeps the bundle lean. |
| **Metadata exported separately** | Keeps the main benchmark logic focused on scoring. |

### How to test

```ts
import { scoreResponse, DEFAULT_PROMPT } from './evaluateTaskPlanning';

describe('scoreResponse', () => {
  it('scores a well‑formatted plan correctly', () => {
    const txt = '1. Prepare ship\n• Gather intel\n2. Execute mission';
    expect(scoreResponse(txt)).toBeCloseTo(0.8);
  });

  it('clamps to 1.0', () => {
    const txt = 'a'.repeat(200); // triggers all regexes
    expect(scoreResponse(txt)).toBe(1.0);
  });
});
```

> **TL;DR** – Pull the magic numbers into constants, factor the regex scoring into a pure helper, split responsibilities, clean imports, and expose a testable API. This makes the code far easier to read, maintain, and extend.

