 *   - Use of type annotations
 *   - Correct return statement
 *   - Existence of comments / documentation
 *   - Basic error‑handling constructs
 *   - Usage of advanced TypeScript features (`export`, `interface`, `type`)
 *   - Balanced opening/closing braces
 *
 * The score is returned as a `Promise<number>`; if the model call fails, the
 * function logs a warning and returns a score of `0`.
 */

/**
 * Metadata for the TypeScript quality benchmark.
 *
 * This object can be consumed by gating and scheduling infrastructure to
 * determine when this benchmark should run.  It currently has no gating
 * dependencies and is classified as a `quality` suite.
 *
 * @type {{suiteType: string, requires: string[]}}
 */
export const typescriptQualityBenchmarkMeta = {
  suiteType: 'quality',
  requires: [],
};

/**
 * Evaluates TypeScript code generation quality and syntax correctness.
 *
 * @param {string} modelId   - Identifier of the model being benchmarked.
 * @param {string} serverId  - Identifier of the server hosting the model.
 * @param {number} [timeoutMs=5 * 60 * 1000] - Timeout for the API call (default 5 min).
 * @param {string} [prompt] - Optional custom prompt; if omitted, a default prompt
 *                            that requests a typed addition function is used.
 *
 * @returns {Promise<number>} A promise that resolves to a score in the range
 *                            [0, 1].  Scores above `0` indicate that the
 *                            generated snippet satisfied some of the quality
 *                            criteria; a score of `0` is returned if the API
 *                            call fails or if the snippet does not meet any
 *                            criterion.
 *
 * @throws {Error} The function does not throw; it catches API errors and logs
 *                 them.  The caller receives a score of `0` in those cases.
 */
export async function evaluateTypescriptQuality(
  modelId: string,
  serverId: string,
  timeoutMs: number = 5 * 60 * 1000,
  prompt?: string
): Promise<number> {
  const defaultPrompt =
    'Write a TypeScript function that adds two numbers with proper type annotations, JSDoc comments, and error handling.';
  const usedPrompt = prompt ?? defaultPrompt;
  const reference = 'function add(a: number, b: number): number { return a + b; }';
  let score = 0;

  try {
    const response = await callModelAPI(
      serverId,
      modelId,
      usedPrompt,
      3,
      500,
      timeoutMs
    );

    // Basic TypeScript syntax checks
    if (/function\s+\w+\s*\(/.test(response)) score += 0.2; // Function declaration
    if (/:\\s*(number|string|boolean)/.test(response)) score += 0.2; // Type annotations
    if (/{\\s*return/.test(response)) score += 0.15; // Return statement

    // Quality indicators
    if (/(\\/\\*\\*|\\/\\/)/.test(response)) score += 0.15; // Comments
    if (/(if\\s*\\(|try\\s*\\{|throw)/.test(response)) score += 0.1; // Error handling
    if (/(export|interface|type)/.test(response)) score += 0.1; // Advanced features

    // Syntax correctness (basic checks)
    const openBraces = (response.match(/\\{/g) || []).length;
    const closeBraces = (response.match(/\\}/g) || []).length;
    if (openBraces === closeBraces) score += 0.1; // Balanced braces
  } catch (err) {
    logger.warn(
      'TypeScript quality error: ' +
        (err instanceof Error ? err.message : String(err))
    );
  }

  return Math.max(0, Math.min(score, 1.0));
}
```

