 * Handles the import of benchmark metadata objects and provides a helper
 * that returns them all in a single array.
 *
 * @module benchmarks/benchmarkMeta
 */

import {
  styleTransferBenchmarkMeta,
  advancedCodeGenerationBenchmarkMeta,
  nodeGraphConstructionBenchmarkMeta,
