## 2. Split the logic into smaller, testable functions

### 2.1. Text analytics helpers

```ts
// src/benchmarks/longFormGeneration/analysis.ts
import type { BenchmarkMetrics } from './types';

const REGEX_PATTERNS = {
  sciFi: [
    /\b(uss|starship|bridge|captain|crew|space|galaxy|star|planet|alien|warp|phaser|transporter|scanner|computer|artificial|android|hologram|shuttle)\b/gi,
    /\b(discovery|enterprise|voyager|defiant|federation|starfleet|command|officer|science|engineering|medical|tactical)\b/gi,
  ],
  dialogue: [
    /["'`].*?["'`]|(?:^|\n)\s*["'].*?["']\s*(?:,|\.|\?|!)/g,
    /\bsaid\b/gi,
    /\basked\b/gi,
    /\breplied\b/gi,
    /\bshout\b/gi,
    /\bwhisper\b/gi,
  ],
  narrative: [
    /\b(watched|observed|noticed|felt|thought|wondered|realized|remembered)\b/gi,
    /\b(suddenly|slowly|carefully|quietly|quickly|immediately)\b/gi,
    /\b(atmosphere|tension|silence|excitement|anticipation|concern)\b/gi,
  ],
  descriptive: [
    /\b(gleaming|massive|imposing|elegant|sophisticated|advanced|mysterious|vast|infinite)\b/gi,
    /\b(systems|controls|displays|panels|corridors|chambers|quarters|deck|hull)\b/gi,
    /\b(humming|pulsing|glowing|flickering|streaming|flowing|radiating)\b/gi,
  ],
  conflict: [
    /\b(mission|danger|threat|conflict|challenge|problem|crisis|emergency|unknown|mysterious)\b/gi,
    /\b(concern|worry|tension|anticipation|uncertainty|risk|responsibility)\b/gi,
  ],
};

export function wordCount(text: string): number {
  return text.trim().split(/\s+/).length;
}

export function paragraphCount(text: string): number {
  return text.split(/\n\s*\n/).filter(p => p.trim()).length;
}

export function countMatches(text: string, pattern: RegExp): number {
  const matches = text.match(pattern);
  return matches ? matches.length : 0;
}

export function scoreFromMatches(
  text: string,
  patterns: RegExp[],
  weightPerMatch: number,
  maxScore: number
): number {
  const totalMatches = patterns.reduce((sum, p) => sum + countMatches(text, p), 0);
  return Math.min(totalMatches * weightPerMatch, maxScore);
}

export function repetitionRatio(text: string): number {
  const sentences = text.split(/[.!?]+/).map(s => s.trim()).filter(Boolean);
  const unique = new Set(sentences.map(s => s.toLowerCase()));
  return unique.size / Math.max(sentences.length, 1);
}
```

*Why?*  
Each helper is tiny, fully typed, and has a single responsibility.  
You can write unit tests for `wordCount`, `paragraphCount`, and `scoreFromMatches` in isolation from the benchmark runner.

---

### 2.2. Scoring strategy objects

```ts
// src/benchmarks/longFormGeneration/rules.ts
import { THRESHOLDS, WEIGHTS } from './constants';
import { REGEX_PATTERNS } from './analysis';

type ScoreFn = (metrics: BenchmarkMetrics, text: string) => number;

export const LENGTH_RULE: ScoreFn = (metrics, text) => {
  const wc = metrics.wordCount;
  let base = 0;

  if (wc >= THRESHOLDS.minLength) base = WEIGHTS.length; // full weight if we meet the minimum
  // add extra points for longer/shorter ranges
  if (wc >= THRESHOLDS.optimalMin && wc <= THRESHOLDS.optimalMax) base += WEIGHTS.bonuses;
  return base;
};

export const GENDER_GEO_RULE: ScoreFn = (metrics, text) => {
  const matches = REGEX_PATTERNS.sciFi.reduce((sum, p) => sum + countMatches(text, p), 0);
  const genreScore = Math.min(matches * 0.01, WEIGHTS.genre); // 0.01 per match, capped
  return genreScore;
};

export const DIALOGUE_RULE: ScoreFn = (metrics, text) => {
  const dlg = REGEX_PATTERNS.dialogue[0];
  const dlgMatches = countMatches(text, dlg);
  const max = Math.min(dlgMatches * 0.05, WEIGHTS.dialogue);
  // the "verb" matches (said, asked…) are treated as *bonus* but capped
  const verbMatches = REGEX_PATTERNS.dialogue.slice(1).reduce((sum, p) => sum + countMatches(text, p), 0);
  const verbBonus = Math.min(verbMatches * 0.01, WEIGHTS.bonuses);
  return max + verbBonus;
};

export const NARRATIVE_RULE: ScoreFn = (metrics, text) => {
  const matches = REGEX_PATTERNS.narrative.reduce((sum, p) => sum + countMatches(text, p), 0);
  return Math.min(matches * 0.02, WEIGHTS.narrative);
};

export const DESCRIPTIVE_RULE: ScoreFn = (metrics, text) => {
  const matches = REGEX_PATTERNS.descriptive.reduce((sum, p) => sum + countMatches(text, p), 0);
  return Math.min(matches * 0.01, WEIGHTS.descriptive);
};

export const CONFLICT_RULE: ScoreFn = (metrics, text) => {
  const matches = REGEX_PATTERNS.conflict.reduce((sum, p) => sum + countMatches(text, p), 0);
  return Math.min(matches * 0.01, WEIGHTS.conflict);
};

export const BLEU_ROUGE_RULE: ScoreFn = (metrics, bleu: number, rouge: number) => {
  const avg = (bleu + rouge) / 2;
  return Math.min(avg * WEIGHTS.blu eRouge, WEIGHTS.blu eRouge);
};
```

> **Tip** – Keep the rule functions small. They can be composed later into a loop that iterates over a *rule map* (`{ length: LENGTH_RULE, genre: GENDER_GEO_RULE, … }`).

