## 3. Build a reusable *ScoreCalculator* (or simply a collection of helper functions)

```ts
// src/benchmarks/longFormGeneration/calculator.ts
import {
  WEIGHTS, THRESHOLDS, REGEX_PATTERNS,
} from './constants';
import {
  wordCount,
  paragraphCount,
  countMatches,
  scoreFromMatches,
  repetitionRatio,
} from './analysis';
import { calculateBleuRouge } from './bleuRouge'; // see below

export interface BenchmarkMetrics {
  wordCount: number;
  paragraphCount: number;
  genreMatches: number;
  dialogueMatches: number;
  narrativeMatches: number;
  descriptiveMatches: number;
  conflictMatches: number;
  bleuScore: number;
  rougeScore: number;
  repetitionRatio: number;
  rawScore: number; // before floor/ceil
}

export function calculateScore(text: string): BenchmarkMetrics {
  const wc = wordCount(text);
  const pc = paragraphCount(text);

  // ---------- length ----------
  const lengthScore =
    (wc >= THRESHOLDS.optimalMin && wc <= THRESHOLDS.optimalMax)
      ? WEIGHTS.length
      : (wc >= THRESHOLDS.minLength ? WEIGHTS.length : WEIGHTS.length * 0.5);

  // ---------- genre ----------
  const sciFiMatches = REGEX_PATTERNS.sciFi.reduce((sum, p) => sum + countMatches(text, p), 0);
  const genreScore = Math.min(sciFiMatches * 0.01, WEIGHTS.genre);

  // ---------- dialogue ----------
  const dlgMarkers = REGEX_PATTERNS.dialogue[0];
  const dlgCount = countMatches(text, dlgMarkers);
  const dialogueScore = Math.min(dlgCount * 0.05, WEIGHTS.dialogue);

  // ---------- narrative ----------
  const narrScore = scoreFromMatches(text, REGEX_PATTERNS.narrative, 0.02);

  // ---------- descriptive ----------
  const descrScore = scoreFromMatches(text, REGEX_PATTERNS.descriptive, 0.01);

  // ---------- conflict ----------
  const conflictScore = scoreFromMatches(text, REGEX_PATTERNS.conflict, 0.01);

  // ---------- bleu / rouge ----------
  const { bleu, rouge } = calculateBleuRouge(text, REFERENCE_TEXT); // implemented later
  const bleuRougeScore = Math.min(((bleu + rouge) / 2) * WEIGHTS.blueRouge, WEIGHTS.blueRouge);

  // ---------- bonuses ----------
  const bonuses = (text.includes('chapter') ? 0.04 : 0) + // chapter bonus
    ((wc >= THRESHOLDS.optimalMin && wc <= THRESHOLDS.optimalMax) ? 0.04 : 0); // optimal length bonus

  // ---------- penalties ----------
  const penaltyFloor = wc < THRESHOLDS.minLength || !isSciFi(text) ? WEIGHTS.penalties : 0;

  // ---------- repetition ----------
  const repRatio = repetitionRatio(text);

  // ---------- assemble ----------
  const rawScore = Math.min(
    1,
    0.02 + // base floor
      lengthScore +
      genreScore +
      dialogueScore +
      narrScore +
      descrScore +
      conflictScore +
      bleuRougeScore +
      bonuses -
      (repRatio < 0.8 ? (repRatio - 0.8) * 0.5 : 0) // simple penalty multiplier
  );

  return {
    wordCount: wc,
    paragraphCount: pc,
    genreMatches: sciFiMatches,
    dialogueMatches: dlgCount,
    narrativeMatches: narrScore,
    descriptiveMatches: descrScore,
    conflictMatches: conflictScore,
    bleuScore: bleu,
    rougeScore: rouge,
    repetitionRatio: repRatio,
    rawScore,
  };
}
```

> **Why?**  
> 1. The *scoring* is now a pure function that receives just a string and returns a metrics object.  
> 2. It’s trivial to write unit tests for each rule (`wordCount`, `paragraphCount`, `scoreFromMatches`, …).  
> 3. The calling code only cares about *what* the score is, not *how* it was derived.

