## 4. Re‑architect `evaluateLongFormGeneration`

```ts
// src/benchmarks/longFormGeneration/benchmark.ts
import { callModelAPI } from '../api'; // your existing wrapper
import { METADATA, DEFAULT_PROMPT, REFERENCE_TEXT } from './constants';
import { calculateScore, BenchmarkMetrics } from './calculator';
import { logger } from '../utils/logger';

export interface BenchmarkResult {
  score: number;
  metrics: BenchmarkMetrics;
}

/**
 * Runs the long‑form generation benchmark.
 *
 * @param modelId   – Identifier for the model (e.g. “gpt‑4”)
 * @param serverId  – Identifier for the deployment host
 * @param prompt    – Optional prompt; falls back to the global default
 * @returns        – Normalised score in the range [0, 1]
 */
export async function runLongFormGenerationBenchmark(
  modelId: string,
  serverId: string,
  prompt?: string,
): Promise<BenchmarkResult> {
  const usedPrompt = prompt ?? DEFAULT_PROMPT;

  try {
    const { text } = await callModelAPI(serverId, modelId, usedPrompt);
    if (!text?.trim()) throw new Error('Empty model output');

    const metrics = calculateScore(text);

    // Structured log – great for CI dashboards or analytics
    logger.info({
      event: 'LongFormGenBenchmark',
      modelId,
      serverId,
      usedPrompt,
      ...metrics,
    });

    return {
      score: metrics.rawScore,
      metrics,
    };
  } catch (err: unknown) {
    logger.error({
      event: 'LongFormGenBenchmarkError',
      modelId,
      serverId,
      prompt: usedPrompt,
      error: (err as Error).message,
    });
    return { score: 0, metrics: { /* zeros… */ } };
  }
}
```

**Note** – `callModelAPI` should return an object with a `text` field; if you still return the whole raw response, just adapt the destructuring accordingly.

