/**
 * Metadata for the “server latency” benchmark.
 *
 * @constant
 * @type {Object}
 * @property {string} suiteType - The benchmark category (`performance`).
 * @property {string[]} requires - Gating dependencies (empty for this suite).
 */
export const serverLatenciesBenchmarkMeta = {
    suiteType: 'performance',
    requires: []
};

/**
 * Measures server‑side inference latency – both cold‑start and warm request times.
 *
 * The routine performs:
 * 1. One *cold* inference to trigger model loading (or a warm‑up if already loaded).
 * 2. Three subsequent *warm* inferences to obtain an average warm latency.
 *
 * Warm latency is measured on the same server that performed the cold request
 * to avoid cache‑flush side‑effects.  The function reports the following:
 *  - `cold`      – Time (ms) of the cold request.
 *  - `warmAvg`   – Mean of the three warm request times.
 *  - `warmup`    – Approximate “warm‑up” time (`cold – warmAvg`).
 *  - `warmAll`   – Array of the raw warm measurements.
 *
 * @param {string} serverId            - Identifier of the target server.
 * @param {string} modelId             - Identifier of the model to be invoked.
 * @param {string} prompt              - Prompt text sent to the model.
 * @param {(serverId:string, modelId:string, prompt:string,
 *          maxRetries?:number, baseDelayMs?:number,
 *          timeoutMs?:number, temperature?:number) => Promise<string>}
 *          callModelAPI  - Async helper that performs the model call.
 * @param {number} [timeoutMs=5*60*1000]  - Request timeout in ms (default: 5 min).
 *
 * @returns {Promise<{
 *   cold: number,
 *   warmAvg: number,
 *   warmup: number,
 *   warmAll: number[]
 * }>}  Latency metrics for the benchmark run.
 *
 * @throws {Error}  The function logs any request failures but never throws;
 *                  errors are captured in the `warmAll` array via a `0`‑ms
 *                  placeholder (if you prefer strict error handling, add your
 *                  own `throw` logic here).
 *
 * @example
 * const metrics = await measureServerLatencies(
 *   'us-east-1',      // serverId
 *   'gpt-4o',         // modelId
 *   'Hello, world!',  // prompt
 *   callModelAPI,     // your API wrapper
 *   300_000           // optional timeout: 5 minutes
 * );
 * console.log(metrics.cold, metrics.warmAvg);
 */
export async function measureServerLatencies(
    serverId,
    modelId,
    prompt,
    callModelAPI,
    timeoutMs = 5 * 60 * 1000
) {
    logger.info(`[Benchmark] [Latencies] Measuring cold latency for server: ${serverId}`);

    const startCold = Date.now();
    try {
        await callModelAPI(serverId, modelId, prompt, 3, 500, timeoutMs);
    } catch (err) {
        logger.warn('Error during cold latency measurement: ' + (err instanceof Error ? err.message : String(err)));
    }
    const cold = Date.now() - startCold;
    logger.info(`[Benchmark] [Latencies] Cold latency: ${cold}ms`);

    const warmAll = [];
    for (let i = 0; i < 3; i++) {
        const startWarm = Date.now();
        try {
            await callModelAPI(serverId, modelId, prompt, 3, 500, timeoutMs);
        } catch (err) {
            logger.warn(`Error during warm latency measurement ${i + 1}: ${err instanceof Error ? err.message : String(err)}`);
        }
        warmAll.push(Date.now() - startWarm);
    }

    const warmAvg = warmAll.reduce((a, b) => a + b, 0) / warmAll.length;
    const warmup = cold - warmAvg;
    logger.info(`[Benchmark] [Latencies] Warm avg: ${warmAvg}ms, Warmup: ${warmup}ms, Warm all: [${warmAll.join(', ')}]ms`);

    return { cold, warmAvg, warmup, warmAll };
}
```

*Why the changes?*

1. **Explicit property annotations** – makes the structure of `serverLatenciesBenchmarkMeta` obvious.
2. **Clearer description of the flow** – readers can instantly see what “cold” and “warm” mean.
3. **Return shape documentation** – shows the exact fields in the result object.
4. **Error‑handling note** – clarifies that the function logs failures but does not throw.
5. **Example usage** – gives a quick recipe for calling the helper.

