### Refactored code sketch (minimal example)

```ts
// benchmarks/measureSimpleServerLatency.ts
/**
 * Benchmark metadata for gating and scheduling
 * @module benchmarks/measureSimpleServerLatency
 */
import { logger } from 'shared/logging/logger.js';

interface BenchmarkMeta {
  suiteType: 'performance';
  requires: readonly string[];
}

export const simpleServerLatencyBenchmarkMeta: BenchmarkMeta = {
  suiteType: 'performance',
  requires: [],
};

const CONFIG = {
  protocol: 'http',
  healthEndpoints: ['/api/tags', '/api/version', '/health'] as const,
  timeoutMs: 5_000,
  fallbackLatencyLabel: 'fallback',
};

const buildUrl = (host: string, path: string) =>
  new URL(path, `${CONFIG.protocol}://${host}`).toString();

async function tryEndpoint(url: string): Promise<boolean> {
  try {
    const res = await fetch(url, {
      method: 'GET',
      signal: AbortSignal.timeout(CONFIG.timeoutMs),
    });
    return res.ok;
  } catch {
    return false;
  }
}

/**
 * Probe the first healthy endpoint of a server and return its latency in ms.
 * Returns `null` if all probes fail.
 */
export async function getServerHealthLatency(
  serverId: string,
  // modelId: string, // drop or document if needed
): Promise<number | null> {
  const start = Date.now();

  // Parallelise probes – take the first successful one.
  const probe = CONFIG.healthEndpoints.map(path =>
    tryEndpoint(buildUrl(serverId, path)).then(ok => (ok ? path : null)),
  );

  const firstSuccess = (await Promise.all(probe)).filter(Boolean)[0] as string | undefined;

  const latency = Date.now() - start;
  if (!firstSuccess) {
    logger.warn(`All health check endpoints failed for ${serverId}`);
    return null;
  }

  logger.debug(`Latency for ${serverId} via ${firstSuccess}: ${latency}ms`);
  return latency;
}
```

