/**
 * Benchmark metadata for the “simple‑server‑latency” suite.
 *
 * @property {string} suiteType   – The type of benchmark. `'performance'`
 *                                  indicates that we’re measuring server latency.
 * @property {string[]} requires  – Gating dependencies; empty for this simple
 *                                  benchmark.
 */
export const simpleServerLatencyBenchmarkMeta = {
    suiteType: 'performance',
    requires: []
};

/**
 * @module benchmarks/measureSimpleServerLatency
 * @description Measures basic server response time with a minimal ping‑style
 * request against a set of health‑check endpoints.
 * @version 1.0.0
 */

import { logger } from 'shared/logging/logger.js';

/**
 * Measure the latency of a server by sending a lightweight GET request to
 * one of its health‑check endpoints.
 *
 * The function tries up to three endpoints (`/api/tags`, `/api/version`,
 * `/health`) and returns the elapsed time in milliseconds for the first
 * successful response. If all endpoints fail or an error occurs, it returns
 * the elapsed time up to that point and logs a warning.
 *
 * @param {string} serverId – Identifier (hostname or IP) of the target server.
 * @param {string} modelId  – Identifier of the model being tested (currently
 *                            unused but kept for API consistency).
 * @returns {Promise<number>} A promise that resolves to the latency in
 *                            milliseconds.
 *
 * @example
 * ```ts
 * const latency = await measureSimpleServerLatency('api.example.com', 'model-123');
 * console.log(`Latency: ${latency}ms`);
 * ```
 */
export async function measureSimpleServerLatency(
    serverId: string,
    modelId: string
): Promise<number> {
    const start = Date.now();
    try {
        // List of health‑check endpoints to try in order.
        const endpoints = [
            `http://${serverId}/api/tags`,
            `http://${serverId}/api/version`,
            `http://${serverId}/health`
        ];

        for (const endpoint of endpoints) {
            try {
                const response = await fetch(endpoint, {
                    method: 'GET',
                    signal: AbortSignal.timeout(5000) // 5 s timeout
                });

                if (response.ok) {
                    const latency = Date.now() - start;
                    logger.debug(
                        `Simple latency for ${serverId}: ${latency}ms (endpoint: ${endpoint})`
                    );
                    return latency;
                }
            } catch {
                // If one endpoint fails, try the next one.
                continue;
            }
        }

        // All endpoints failed; report the elapsed time.
        logger.warn(`All health check endpoints failed for server: ${serverId}`);
        return Date.now() - start;
    } catch (err) {
        logger.warn(
            `Error during simple latency measurement for ${serverId}: ${
                err instanceof Error ? err.message : String(err)
            }`
        );
        return Date.now() - start;
    }
}
