### Refactored code (excerpt)

```ts
// constants.ts
export const PROBE_PROMPT = 'ping';
export const MAX_TOKENS = 1;
export const TEMPERATURE = 1;
export const DEFAULT_TIMEOUT_MS = 2000;

// probeTypes.ts
/** Result of a probe (1 = healthy, 0 = unhealthy). */
export enum ProbeResult {
  Healthy = 1,
  Unhealthy = 0,
}

// performanceProbe.ts
import { callModelAPI } from '../benchmarkUtils.js';
import { logger } from 'shared/logging/logger.js';
import {
  PROBE_PROMPT,
  MAX_TOKENS,
  TEMPERATURE,
  DEFAULT_TIMEOUT_MS,
} from './constants.js';
import { ProbeResult } from './probeTypes.js';

export const performanceProbeBenchmarkMeta = {
  suiteType: 'performance',
  requires: [],
} as const;

function logLatency(serverId: string, modelId: string, latency: number) {
  // Use trace for high‑frequency probes; switch to info if needed
  logger.trace(
    `Performance probe for ${modelId}@${serverId}: latency ${latency}ms`
  );
}

export async function performanceProbe(
  serverId: string,
  modelId: string,
  timeoutMs = DEFAULT_TIMEOUT_MS,
  probePrompt = PROBE_PROMPT
): Promise<ProbeResult> {
  const start = Date.now();
  try {
    const response = await callModelAPI(
      serverId,
      modelId,
      probePrompt,
      MAX_TOKENS,
      TEMPERATURE,
      timeoutMs
    );

    const latency = Date.now() - start;
    logLatency(serverId, modelId, latency);

    if (typeof response === 'string' && response.trim() !== '') {
      return ProbeResult.Healthy;
    }
    return ProbeResult.Unhealthy;
  } catch (err) {
    logger.warn(
      `Performance probe failed for ${modelId}@${serverId}: ${
        err instanceof Error ? err.message : String(err)
      }`
    );
    return ProbeResult.Unhealthy;
  }
}
```

