import { safeBleu, safeRouge } from '../metrics';
import { logger } from './shared/logging/logger';
``` |
| 2 | **Move the default prompt to a module‑level constant** | The prompt is static; creating it on every call is wasteful and makes the function harder to read. Use a multiline template literal to preserve formatting. | ```ts
const DEFAULT_PROMPT = `You are a creative writing critic.  
Evaluate the following short story for: <br/>
• Logical coherence<br/>
• Narrative structure<br/>
• Character consistency…` ;  // keep \n for readability
``` |
| 3 | **Introduce a config object for scoring constants** | All “magic” numbers (base score, increments, thresholds, weights) should be named constants. That lets you tweak a single place and makes the intent obvious. | ```ts
const BASE_SCORE = 0.2;
const SCORING = {
  LOGIC: {
    PRESENT: 0.15,
    INCLUDES: 0.05,
    PLOT_HOLES: 0.1,
  },
  STRUCTURE: { BEATS: 0.1, NO_CONTRADICTION: 0.05 },
  CHAR: { PRESENT: 0.05, INCLUDES: 0.05 },
  DETAIL: { SHORT: 0.05, LONG: 0.05 },
  FLOW: { WORDS: 0.05 },
  BLEU_ROUGE: 0.05,
  DEFAULT_TIMEOUT_MS: 5 * 60 * 1000,
};
``` |
| 4 | **Extract regex patterns into constants** | Regex literals appear dozens of times; compile them once and reuse. It also avoids typos and makes updates easier. | ```ts
const PATTERNS = {
  PRESENT: /(?:artifact|chen|sarah|energy|electronic|malfunction)/i,
  BEATS: /(beat|step|\d+\.|first|second|third|next|then|finally)/i,
  NO_CONTRADICTION: /(contradiction|inconsistent|simultaneously.*later|before.*after)/i,
  PLOT_HOLES: /(suddenly.*for no reason|inexplicably|without explanation|magic|impossible)/i,
  NO_PROGRESSION: /(artifact|energy|malfunction|chen)/i,
};
``` |
| 5 | **Split scoring into small pure helper functions** | `evaluatePlotCoherence` is a God‑function. Each scoring rule can live in its own function that receives the model output and returns the partial score. | ```ts
function computeLogicScore(text: string): number {
  let score = 0;
  if (PATTERNS.PRESENT.test(text)) score += SCORING.LOGIC.PRESENT;
  // ...more rules
  return score;
}
``` |
| 6 | **Use a mapping / array of criteria** | Rather than hard‑coding many `if (PATTERN.test(text)) { score += X; }` blocks, store criteria in an array of objects (`{ pattern, weight }`) and iterate. | ```ts
const LOGIC_CRITERIA: Array<{ pattern: RegExp; weight: number }> = [
  { pattern: /(?:artifact|sarah|energy)/i, weight: 0.15 },
  { pattern: /(?:electronic|malfunction)/i, weight: 0.05 },
  // …
];
function computeLogicScore(text: string): number {
  return LOGIC_CRITERIA.reduce((s, c) => c.pattern.test(text) ? s + c.weight : s, 0);
}
``` |
| 7 | **Early return for API errors** | The outer `try…catch` is nested inside all scoring logic. Catch the API failure first, log, and return the default error score immediately. | ```ts
try {
  const response = await callModelAPI(options);
  if (typeof response !== 'string') throw new Error('Non‑string response');
  text = response.trim();
} catch (err) {
  logger.warn(`Plot coherence evaluation failed: ${err}`);
  return 0;   // or 0.1 if you want a non‑zero “fail” score
}
``` |
| 8 | **Replace string concatenation in logs with template literals** | Keeps logs consistent and easier to read. | ```ts
logger.warn(`Plot coherence BLEU/ROUGE error: ${err}`);
``` |
| 9 | **Add full TypeScript types** | Every helper, constant, and object should be typed. Even the small `hasConceptualConnection` helper gets an explicit return type. | ```ts
function hasConceptualConnection(a: string, b: string): boolean { … }
``` |
| 10 | **Move references and metadata to a separate config file** | If you ever need multiple reference passages or multiple benchmarks, keep them out of the logic layer. | ```ts
export const PLOT_COHERENCE_REFERENCE = `The sky was…`;
export const PLOT_COHERENCE_BENCHMARK_META = {
  name: 'plot‑coherence',
  description: 'Evaluates logical consistency…',
  version: '1.0',
} as const;
``` |
| 11 | **Normalize punctuation split** | `text.split(/[.!?]+/)` sometimes leaves empty strings; filter them out. | ```ts
const sentences = text.split(/[.!?]+/).filter(Boolean);
``` |
| 12 | **Use object options for `callModelAPI`** | The arguments `3, 500` are magic numbers. Replace with a typed options object. | ```ts
await callModelAPI({ serverId, modelId, prompt: usedPrompt, maxTokens: 3, timeoutMs, temperature: 0.5 });
``` |
| 13 | **Wrap BLEU/ROUGE calculation in its own async helper** | This isolates error handling for metrics and keeps the main flow cleaner. | ```ts
async function computeBleuRouge(text: string): Promise<{ bleu: number; rouge: number }> {
  try {
    const bleu = await safeBleu(text, [REFERENCE]);   // if safeBleu is async
    const rouge = safeRouge(text, REFERENCE);
    return { bleu, rouge };
  } catch (e) {
    logger.warn(`BLEU/ROUGE calculation failed: ${e}`);
    return { bleu: 0, rouge: 0 };
  }
}
``` |
| 14 | **Add JSDoc for public API** | Document `@param`, `@returns`, and any notable behaviour (e.g., clamping to 0–1). | ```ts
