#### Quick refactor sketch

```ts
// helpers.ts
export function isValidString(str: unknown): str is string {
  return typeof str === 'string' && str.trim() !== '';
}

export function tokenise(text: string): string[] {
  return text.toLowerCase().trim().split(/\s+/).filter(Boolean);
}

export function countCommonWords(a: string[], b: string[]): number {
  const bSet = new Set(b);
  return a.reduce((sum, w) => (bSet.has(w) ? sum + 1 : sum), 0);
}

export function computeF1(precision: number, recall: number): number {
  return precision + recall > 0 ? (2 * precision * recall) / (precision + recall) : 0;
}

export function logRougeMetrics(recall: number, precision: number, f1: number) {
  logger.debug(`ROUGE: recall=${recall}, precision=${precision}, f1=${f1}`);
}
```

```ts
// safeRouge.ts
import {
  isValidString,
  tokenise,
  countCommonWords,
  computeF1,
  logRougeMetrics,
} from './helpers';

export function safeRouge(candidate: string, reference: string): number {
  try {
    if (!isValidString(candidate) || !isValidString(reference)) {
      return 0;
    }

    const candTokens = tokenise(candidate);
    const refTokens = tokenise(reference);

    if (!candTokens.length || !refTokens.length) {
      return 0;
    }

    const lcs = countCommonWords(candTokens, refTokens);
    const recall = lcs / refTokens.length;
    const precision = lcs / candTokens.length;
    const f1 = computeF1(precision, recall);

    logRougeMetrics(recall, precision, f1);
    return Math.max(0, Math.min(1, f1));
  } catch (err) {
    logger.warn(`Error calculating ROUGE score: ${err instanceof Error ? err.message : String(err)}`);
    return 0;
  }
}
```

This refactor preserves the original behavior while improving clarity, testability, and DRY compliance.

