## Refactored Example (TypeScript)

```ts
/**
 * Fastest Server Selection
 *
 * @module benchmarks/selectFastestServer
 * @version 1.0.0
 */

import { measureSimpleServerLatency } from "./measureSimpleServerLatency.js";
import { logger } from "shared/logging/logger.js";

/** Public alias for a server identifier. */
export type ServerId = string;

/**
 * Returns the latency of a single server.
 * On failure the function resolves to `Number.MAX_SAFE_INTEGER`
 * so that the caller can ignore it safely.
 */
async function getLatency(server: ServerId, modelId: string): Promise<number> {
  try {
    const latency = await measureSimpleServerLatency(server, modelId);
    logger.debug(`Server ${server} latency: ${latency}ms`);
    return latency;
  } catch (e) {
    logger.warn(
      `Error measuring latency for ${server}: ${
        e instanceof Error ? e.message : e
      }`
    );
    return Number.MAX_SAFE_INTEGER;
  }
}

/**
 * Selects the server with the lowest measured latency.
 *
 * @param servers   Array of server identifiers to test
 * @param modelId   The model identifier to test with
 * @returns The fastest server identifier, or `null` if none could be measured.
 */
export async function selectFastestServer(
  servers: ServerId[],
  modelId: string
): Promise<ServerId | null> {
  // Input validation
  if (!Array.isArray(servers) || servers.length === 0) {
    throw new Error("No servers provided for selection");
  }

  // Quick exit when only one candidate
  if (servers.length === 1) return servers[0];

  logger.info(`[Benchmark] Selecting fastest server from ${servers.length} candidates`);

  // Measure all latencies in parallel
  const latencyPromises = servers.map((s) => getLatency(s, modelId));
  const latencies = await Promise.all(latencyPromises);

  // Find the server with the smallest latency
  const fastestIndex = latencies.reduce(
    (best, curr, idx) => (curr < latencies[best] ? idx : best),
    0
  );

  const fastestServer = servers[fastestIndex];
  const lowestLatency = latencies[fastestIndex];

  // If the fastest latency is still `Number.MAX_SAFE_INTEGER`, all measurements failed.
  if (lowestLatency === Number.MAX_SAFE_INTEGER) {
    logger.warn("[Benchmark] No server could be measured successfully");
    return null;
  }

  logger.info(
    `[Benchmark] Selected fastest server: ${fastestServer} (${lowestLatency}ms)`
  );
  return fastestServer;
}
```

### What Changed?

| Area | What changed | Benefit |
|------|--------------|---------|
| **Types** | Introduced `ServerId` alias | Self‑documenting and type‑safe |
| **Helper** | `getLatency` isolates measurement logic | Reusable & easier to test |
| **Error handling** | `Promise.allSettled` → `Promise.all` + internal `try/catch` | Single point of error handling |
| **State** | Removed mutable `fastestServer / lowestLatency` | Declarative, no side‑effects |
| **Return value** | `null` when no server can be selected | Clear contract for callers |
| **Logging** | Structured & consistent | Easier to filter/parse logs |
| **Validation** | Explicit array check | Defensive programming |
| **Performance** | Parallel measurement & `reduce` | O(n) time, O(n) memory |

---

