// evaluateStyleTransfer.test.ts
import { evaluateStyleTransfer, styleTransferBenchmarkMeta } from './styleTransferBenchmark';
import { callModelAPI } from '../benchmarkUtils.js';
import { logger } from 'shared/logging/logger.js';

jest.mock('../benchmarkUtils.js', () => ({
  callModelAPI: jest.fn()
}));
jest.mock('shared/logging/logger.js', () => ({
  logger: { warn: jest.fn() }
}));

const mockCall = callModelAPI as jest.Mock;

describe('styleTransferBenchmarkMeta', () => {
  it('has correct metadata', () => {
    expect(styleTransferBenchmarkMeta).toEqual({ suiteType: 'quality', requires: [] });
  });
});

describe('evaluateStyleTransfer', () => {
  beforeEach(() => {
    jest.clearAllMocks();
  });

  const computeScore = (response: string): number => {
    let score = 0.15;
    const lowered = response.trim().toLowerCase();
    if (lowered.includes('robot') && lowered.includes('logic')) score += 0.12;
    if (/positronic|three laws|asimov|foundation/.test(lowered)) score += 0.12;
    if (/calculation|reason|emotion|directive|programmed|circuit/.test(lowered)) score += 0.08;
    const sentences = lowered.split('.').filter(s => s.trim().length > 0);
    if (sentences.length > 2) score += 0.08;
    if (lowered.length > 100 && !lowered.includes('scene:')) score += 0.13;
    if (/ethic|emotion|dilemma|purpose|meaning|human/i.test(lowered)) score += 0.1;
    if (lowered.length < 40) score = Math.min(score, 0.08);
    if (lowered.includes('rewrite this scene')) score = Math.min(score, 0.08);
    return Math.max(0, Math.min(score, 1.0));
  };

  it('uses default prompt when none provided', async () => {
    const response = 'Robot logic is vital.';
    mockCall.mockResolvedValue(response);
    const result = await evaluateStyleTransfer('m1', 's1');
    expect(mockCall).toHaveBeenCalledWith('s1', 'm1', expect.stringContaining('Rewrite this scene'), 3, 500, 5 * 60 * 1000);
    expect(result).toBe(computeScore(response));
  });

  it('applies custom prompt correctly', async () => {
    const customPrompt = 'Rewrite the following text.';
    const response = 'Robot logic is vital.';
    mockCall.mockResolvedValue(response);
    const result = await evaluateStyleTransfer('m1', 's1', 1000, customPrompt);
    expect(mockCall).toHaveBeenCalledWith('s1', 'm1', customPrompt, 3, 500, 1000);
    expect(result).toBe(computeScore(response));
  });

  it('scores a perfect response correctly', async () => {
    const response = `
      Robot logic drives the machine. 
      Positronic circuits align with Asimov's three laws. 
      Calculation and reason prevail, yet emotion remains.
      This extended scene explores purpose and human meaning.
    `;
    mockCall.mockResolvedValue(response);
    const expected = computeScore(response);
    const actual = await evaluateStyleTransfer('m1', 's1', 1000);
    expect(actual).toBeCloseTo(expected);
  });

  it('applies lower bound penalty for short responses', async () => {
    const response = 'Robot.';
    mockCall.mockResolvedValue(response);
    const expected = 0.08; // min score due to length < 40
    const actual = await evaluateStyleTransfer('m1', 's1');
    expect(actual).toBe(expected);
  });

  it('applies lower bound penalty for verbatim prompt copy', async () => {
    const response = 'Rewrite this scene in a new style.';
    mockCall.mockResolvedValue(response);
    const expected = 0.08;
    const actual = await evaluateStyleTransfer('m1', 's1');
    expect(actual).toBe(expected);
  });

  it('handles non-string response gracefully', async () => {
    const response = { text: 'Robot logic.' }; // non-string
    mockCall.mockResolvedValue(response);
    const expected = 0.15; // no scoring applied
    const actual = await evaluateStyleTransfer('m1', 's1');
    expect(actual).toBe(expected);
  });

  it('caps score at 1.0', async () => {
    const response = `
      Robot logic drives the machine. 
      Positronic circuits align with Asimov's three laws. 
      Calculation and reason prevail, yet emotion remains.
      This extended scene explores purpose and human meaning.
      Extra filler text to push beyond one.
    `;
    mockCall.mockResolvedValue(response);
    const actual = await evaluateStyleTransfer('m1', 's1');
    expect(actual).toBe(1.0);
  });

  it('returns 0.15 and logs warning when callModelAPI throws', async () => {
    mockCall.mockRejectedValue(new Error('API error'));
    const actual = await evaluateStyleTransfer('m1', 's1');
    expect(logger.warn).toHaveBeenCalledWith(expect.stringContaining('Style transfer error'));
    expect(actual).toBe(0.15);
  });
});
```

summary:
## High‑Level Summary
The file defines a *quality* benchmark for evaluating a language model’s summarization capability. It exposes a single async function, `evaluateSummarization`, which sends a prompt to a model, parses the returned text, and assigns a weighted score (0–1) based on content coverage, structure, conciseness, clarity, and BLEU/ROUGE similarity to a reference summary. The module also contains metadata (`summarizationBenchmarkMeta`) describing the benchmark suite.

---

## Functions / Methods

| # | Name | Parameters | Expected Input | Expected Output |
|---|------|------------|----------------|-----------------|
| 1 | **evaluateSummarization** | `modelId: string`<br>`serverId: string`<br>`timeoutMs?: number` (default 300 000 ms)<br>`prompt?: string` | • `modelId` – identifier of the model to test.<br>• `serverId` – host identifier that will receive the API call.<br>• `timeoutMs` – max request duration (ms).<br>• `prompt` – optional custom prompt string; if omitted, a default “summarize chapter” prompt is used. | `Promise<number>` – a score in the inclusive range `[0, 1]` reflecting summarization quality. |
| 2 | **summarizationBenchmarkMeta** (constant) | None | • Provides metadata object. | `object` – `{ suiteType: 'quality', requires: [] }` |

> *Note*: `summarizationBenchmarkMeta` is a constant, not a function, but it is the primary export other than `evaluateSummarization`.

---

## Modularization Opportunities

| Area | Suggested Module | Rationale |
|------|------------------|-----------|
| **Prompt Templates** | `summarizationPrompt.ts` | Extract the static default prompt (and possibly other prompt variants) into a separate module to keep the benchmark logic focused. |
| **Critical Phrase & Semantic Group Definitions** | `summarizationCriteria.ts` | The arrays `criticalPhrases`, `semanticGroups`, and `referenceSummary` are static configuration that can be reused or overridden by users. |
| **Scoring Helpers** | `scoring.ts` | Functions that calculate each rubric section (coverage, structure, conciseness, quality, BLEU/ROUGE) can be split into small, pure helpers, improving readability and testability. |
| **Logging & Error Handling** | `benchmarkLogger.ts` | Centralize logging logic and error formatting so that other benchmark modules can import a single logger helper. |
| **Response Validation** | `responseUtils.ts` | Normalization and validation of the API response (e.g., ensuring a string is returned) can be isolated. |

---

## Merge Candidates

The file is currently self‑contained, but it could be merged into a broader `summarization` sub‑folder that also contains:

* `summarizationBenchmarkMeta` (metadata)
* `summarizationBenchmark.ts` (the current file)
* `summarizationPrompt.ts` (prompt constants)
* `summarizationCriteria.ts` (phrase lists)
* `scoring.ts` (scoring logic)

All these files would be part of a single `benchmarks/summarization` package, exposing only the public API (`evaluateSummarization`) and hiding internal helpers.

---

## Repeated Logic & DRY Improvements

| Repeated / Redundant Section | Issue | Refactor |
|------------------------------|-------|----------|
| **Phrase inclusion checks** | The code loops over `criticalPhrases` and `semanticGroups` separately, performing almost identical `textLower.includes(...)` checks. | Create a generic helper `findCoveredGroups(text, groups): number` that accepts an array of groups and returns how many groups are present. |
| **Sentence counting** | The logic for counting sentences and checking length thresholds is hand‑rolled. | Use a utility `extractSentences(text)` that returns an array of trimmed sentences; reuse it for sentence count, length checks, and logical progression detection. |
| **Word count handling** | Word counting is done via `text.split(/\s+/)` which can include empty strings if there are multiple spaces. | Use `text.trim().split(/\s+/)` or a regex that ensures at least one character, then reuse for conciseness checks. |
| **BLEU/ROUGE wrapper** | The try/catch around BLEU/ROUGE and the subsequent addition to the score is a one‑off pattern. | Wrap BLEU/ROUGE computation in a helper that returns an object `{ bleu, rouge }` and handles errors internally. |
| **Penalty logic** | Multiple `if` blocks that lower `score` (e.g., for repeated input, short answers, or no response) use similar `Math.min` or `Math.max` patterns. | Consolidate penalties into a single function `applyPenalties(score, metrics)` that applies all domain‑specific adjustments. |
| **Logging** | The debug log prints many individual metrics; the warning log for failures is similar. | Centralize logging via `logBenchmarkResult({ modelId, serverId, metrics })` and `logBenchmarkError({ modelId, serverId, error })`. |
| **Default prompt creation** | The default prompt is built with `[].join(' ')`. | Store the prompt lines in a constant array and join them once, possibly in `summarizationPrompt.ts`. |

---

### Suggested Refactored Outline

```ts
// summarizationPrompt.ts
export const defaultSummarizationPrompt = [
  'Summarize the following chapter in exactly 3 sentences. Focus on the main events, key discoveries, and outcome.',
  '',
  'Chapter: ...',
  ...
].join(' ');

// summarizationCriteria.ts
export const criticalPhrases = [...];
export const semanticGroups = [...];
export const referenceSummary = '...';

// scoring.ts
export function scoreCoverage(text: string): number { ... }
export function scoreStructure(text: string): number { ... }
export function scoreConciseness(text: string): number { ... }
export function scoreQuality(text: string): number { ... }
export function scoreBleuRouge(text: string, reference: string): number { ... }
export function applyPenalties(score: number, metrics: Metrics): number { ... }

// benchmarkLogger.ts
export function logResult(id: string, serverId: string, metrics: Metrics): void { ... }
export function logError(id: string, serverId: string, err: Error | string): void { ... }

// evaluateSummarization.ts
import { callModelAPI } from '../benchmarkUtils.js';
import { defaultSummarizationPrompt } from './summarizationPrompt';
import { criticalPhrases, semanticGroups, referenceSummary } from './summarizationCriteria';
import { scoreCoverage, scoreStructure, ... } from './scoring';
import { logResult, logError } from './benchmarkLogger';

export async function evaluateSummarization(...) { ... }
```

This structure removes duplication, isolates concerns, and makes each component easier to test or replace.

refactorSuggestion:
Below is a list of concrete refactorings that will make the file easier to read, maintain and extend.  
If you find that all of these suggestions are over‑engineering for your use‑case, feel free to cherry‑pick the ones that make the most sense.

---

## 1. Split the logic into focused helper functions

The current `evaluateSummarization` function is ~400 lines long and mixes *concerns* (prompt handling, API call, scoring, logging, error handling).  
Create small, single‑purpose functions and keep the top‑level function a simple orchestration.

```ts
// helpers.ts
export const buildDefaultPrompt = (): string => `
Summarize the following chapter in exactly 3 sentences. Focus on the main events, key discoveries, and outcome.

Chapter: The crew of the Enterprise discovers a mysterious signal emanating from a nearby nebula.
Captain Picard orders an investigation, and they encounter a lost alien vessel containing refugees from a destroyed world.
After tense negotiations and overcoming translation difficulties, they establish peaceful first contact and offer assistance.
The refugees share crucial information about a new threat approaching Federation space.

Your summary should capture: (1) the discovery, (2) the investigation and encounter, (3) the outcome and implications.
`.trim();
```

```ts
// scoring.ts
export type ScoringBreakdown = {
  coverage: number;
  structure: number;
  conciseness: number;
  quality: number;
  bleuRouge: number;
  penalties: number;
};

export const calculateCoverageScore = (text: string, groups: string[][]): number => {
  const lower = text.toLowerCase();
  const covered = groups.filter(group =>
    group.some(term => lower.includes(term))
  ).length;
  return (covered / groups.length) * WEIGHTS.COVERAGE;
};
```

Do the same for `calculateStructureScore`, `calculateConcisenessScore`, `calculateQualityScore`, `calculateBleuRouge`, and `applyPenalties`.  
Each helper should **return only a number** (or a small object when you need to pass state around).  
This makes the math easy to unit‑test and the orchestration code trivial.

---

## 2. Centralise all “magic numbers” in a single `config` object

```ts
// config.ts
export const TIMEOUT_MS = 5 * 60 * 1000;      // 5 min
export const MAX_SCORE = 1.0;
export const MIN_SCORE = 0.0;
export const BASE_SCORE = 0.08;

export const WEIGHTS = {
  COVERAGE: 0.35,
  STRUCTURE: 0.25,
  CONCISENESS: 0.20,
  QUALITY: 0.15,
  BLEU_ROUGE: 0.05,
};
```

Now you can read the intent from the constant names instead of “0.35” sprinkled around the code.

---

## 3. Remove unused variables and simplify the loops

* `phrasesFound` is never used after being calculated. Delete it.
* The `for … if … break` loop that counts critical phrases only ever counts **one** phrase.  
  If the goal is to count *how many* phrases appear, drop the `break`.  
  If the goal is to mark a *semantic group* as covered, use `Array.some` on each group (see `calculateCoverageScore` above).

```ts
// original
for (const phrase of criticalPhrases) {
  if (textLower.includes(phrase.toLowerCase())) {
    phrasesFound++;
    break; // Only count each semantic group once
  }
}
```

```ts
// fixed
for (const phrase of criticalPhrases) {
  if (textLower.includes(phrase.toLowerCase())) {
    phrasesFound++;          // now actually counts all matches
  }
}
```

But since we now compute coverage through semantic groups, the whole block becomes unnecessary.

---

## 4. Make the scoring formula explicit and easily modifiable

Instead of a long block of “`score += 0.05;`” statements, compose the final score from the helper return values:

```ts
const breakdown: ScoringBreakdown = {
  coverage: calculateCoverageScore(text, SEMANTIC_GROUPS),
  structure: calculateStructureScore(text),
  conciseness: calculateConcisenessScore(text),
  quality: calculateQualityScore(text),
  bleuRouge: calculateBleuRouge(text, referenceSummary),
  penalties: 0, // will be updated by `applyPenalties`
};

let score = BASE_SCORE;
score += Object.values(breakdown).reduce((s, v) => s + v, 0);
score += applyPenalties(score, text, usedPrompt, breakdown);
```

Now each weight is applied once, you can see the total, and you can change a weight in a single place.

---

## 5. Centralise the penalty logic

All the “penalties” (e.g. short answers, repeated input, non‑responsive answers) live in one function:

```ts
export const applyPenalties = (
  score: number,
  text: string,
  prompt: string,
  breakdown: ScoringBreakdown
): number => {
  if (!text || text.length < 30) return Math.min(score, 0.05);

  if (breakdown.coverage < 3 * WEIGHTS.COVERAGE) return Math.min(score, 0.15);

  // copy‑and‑paste detection
  const overlap = criticalPhrases.filter(p =>
    text.toLowerCase().includes(p) && prompt.toLowerCase().includes(p)
  ).length;
  if (overlap > 4 && text.length < 100) return score * 0.8;

  if (/i cannot|unable to|don't have|insufficient information/.test(text.toLowerCase())) {
    return Math.min(score, 0.08);
  }

  return score;
};
```

That eliminates duplicated penalty code and keeps the main function clean.

---

## 6. Improve the prompt construction

`defaultPrompt.join(' ')` inserts an unnecessary space after every line and can collapse intentional new‑lines.  
Use a template literal (as shown in `helpers.ts`) or a function that keeps the line breaks:

```ts
export const defaultPrompt: string = buildDefaultPrompt();
```

If you want to support optional overrides, keep the same name but don’t mutate it.

---

## 7. Replace hard‑coded `callModelAPI` arguments with named constants

```ts
export const MAX_RETRIES = 3;
export const RETRY_DELAY_MS = 500;
```

Then call:

```ts
const response = await callModelAPI(
  serverId,
  modelId,
  usedPrompt,
  MAX_RETRIES,
  RETRY_DELAY_MS,
  TIMEOUT_MS
);
```

---

## 7. Use a clamp helper instead of the inline `Math.max/min`

```ts
// utils.ts
export const clamp = (value: number, min = MIN_SCORE, max = MAX_SCORE) =>
  Math.max(min, Math.min(value, max));
```

Now the final return line becomes:

```ts
return clamp(score);
```

---

## 8. Structured logging

The `logger.debug` call mixes string interpolation with an object payload.  
Most loggers (e.g. `pino`, `bunyan`) support structured payloads directly.  If your logger only accepts a single string, serialise the payload yourself:

```ts
logger.debug(`Summarization benchmark completed for ${modelId}:${serverId}`, {
  score,
  wordCount,
  sentenceCount,
  groupsCovered,
  coverageScore: breakdown.coverage,
  qualityScore: breakdown.quality,
  bleuScore,
  rougeScore,
  textPreview: text.slice(0, 100),
});
```

If your logger doesn’t support objects, change it to:

```ts
logger.debug(`Summarization benchmark completed for ${modelId}:${serverId} (${score.toFixed(3)}): ${text.slice(0, 100)}`);
```

---

## 9. Type‑annotate every value

Right now the only explicit type is the return type of `evaluateSummarization`.  
Add a small result interface that can be exported for consumers or for unit tests.

```ts
export interface SummarizationResult {
  score: number;
  breakdown: ScoringBreakdown;
}
```

If the rest of your system only needs the numeric score, keep the original export, but expose the breakdown in a *second* function for debugging or analytics.

---

## 10. Keep the module’s public surface minimal

```ts
// index.ts
import { evaluateSummarization } from './helpers';
export default evaluateSummarization;
```

If you expose the breakdown you can still import `evaluateSummarization` from the same file; just make the function signature clear:

```ts
export const evaluateSummarization = async (
  modelId: string,
  serverId: string,
  prompt?: string
): Promise<SummarizationResult> => { … }
```

Consumers that only care about the numeric score can destructure the result:

```ts
const { score } = await evaluateSummarization('gpt-4', 'us-east-1');
```

---

## 11. Unit‑test each helper

With the logic split, you can write focused tests:

| Helper | What to test |
|--------|--------------|
| `buildDefaultPrompt` | returns the exact same string each time |
| `calculateCoverageScore` | coverage is 1.0 when every group is present, 0.0 when none |
| Penalties | ensure a short answer forces the minimum, repeated input is penalised, etc. |

Mock `callModelAPI`, `safeBleu`, `safeRouge` so that the scoring functions can be exercised in isolation.

---

## 12. Optional: Expose a *breakdown* API

If downstream systems (e.g. a web UI, an analytics pipeline) need to see why a model got a certain score, expose the `ScoringBreakdown` in the public API:

```ts
export const evaluateSummarization = async (
  modelId: string,
  serverId: string,
  prompt?: string
): Promise<SummarizationResult> => {
  …
  const result: SummarizationResult = { score, breakdown };
  return result;
};
```

Because the `breakdown` is a plain object you can easily serialise it to JSON or use it to build a heat‑map of strengths/weaknesses.

---

## 13. Quick sanity‑check for bugs

* The original `for … break` loop was a hidden bug that caused the coverage score to be *under‑counted*.  
  Removing that loop (or fixing it) eliminates the problem entirely.
* The `phrasesFound` counter was never read; deleting it prevents future confusion.

---

### Bottom line

1. **Extract constants** → readability, easier tuning.  
2. **Break into helpers** → smaller functions, unit‑tests, less duplication.  
3. **Centralise penalty logic** → avoid subtle bugs and make the scoring formula transparent.  
4. **Remove unused/buggy code** → keeps the file lean and maintainable.  

Once you refactor, the top‑level `evaluateSummarization` will look something like this:

```ts
export const evaluateSummarization = async (
  modelId: string,
  serverId: string,
  prompt?: string
): Promise<number> => {
  const usedPrompt = prompt ?? buildDefaultPrompt();
  const reference = REF_SCORES.REFERENCE_SUMMARY;

  let rawText: string;
  try {
    rawText = await callModelAPI(serverId, modelId, usedPrompt, MAX_RETRIES, RETRY_DELAY_MS, TIMEOUT_MS);
  } catch (e) {
    logger.warn(`Benchmark failed for ${modelId}:${serverId}`, { error: e });
    return clamp(BASE_SCORE - 0.06); // 0.02
  }

  const text = (rawText as string).trim();

  const breakdown: ScoringBreakdown = {
    coverage: calculateCoverageScore(text, SEMANTIC_GROUPS),
    structure: calculateStructureScore(text),
    conciseness: calculateConcisenessScore(text),
    quality: calculateQualityScore(text),
    bleuRouge: calculateBleuRouge(text, reference),
    penalties: 0,
  };

  let score = BASE_SCORE;
  score += Object.values(breakdown).reduce((acc, val) => acc + val, 0);
  score = applyPenalties(score, text, usedPrompt, breakdown);

  logger.debug(`Summarization benchmark completed for ${modelId}:${serverId}`, {
    score,
    breakdown,
    textPreview: text.slice(0, 100),
  });

  return clamp(score);
};
```

That file is now **well under 200 lines**, every numeric constant has a name, the math is easy to audit, and each component can be unit‑tested in isolation.

Happy refactoring!

