```

> **Tip** – you can keep the *narrative* rule out of the data‑driven config because it needs a bit more logic; just expose it as a small helper.

### 3.2 `worldBuildingUtils.ts`

```ts
// worldBuildingUtils.ts
import { WORLD_BUILDING_CONFIG } from './config';
import { safeBleu, safeRouge } from '../benchmarkUtils';
import { logger } from 'shared/logging/logger';

/**
 * Evaluate the textual output against all score categories.
 * @param text The model's output
 * @returns An object with a final score and a breakdown per category.
 */
export function computeWorldBuildingScore(text: string): WorldBuildingScore {
  const { baseScore, minScore, maxScore, reference, scoringRules } = WORLD_BUILDING_CONFIG;

  // ---- helpers ----
  const regexTest = (p: RegExp) => p.test(text);
  const applyRule = (rules: Rule[], weight: number) =>
    rules.reduce((acc, r) => (regexTest(r.pattern) ? acc + weight : acc), 0);

  // ---- category scores ----
  const completenessScore = applyRule(scoringRules.completeness, 0.08);
  const consistencyScore = applyRule(
    scoringRules.consistency.map(r => ({ pattern: new RegExp(''), weight: r.weight, condition: r.condition })),
    0 // we'll use condition logic inside
  );
  // Build consistency from condition logic
  let consistencyScoreVal = 0;
  for (const r of scoringRules.consistency) {
    if (r.condition(text)) consistencyScoreVal = Math.max(consistencyScoreVal, r.weight);
  }

  // The rest of the categories are built the same way …
  const detailScore = 0;      // placeholder
  const creativityScore = 0;  // placeholder
  const realismScore = 0;     // placeholder
  const depthScore = 0;       // placeholder
  const terminologyScore = 0; // placeholder
  const narrativeScore = 0;   // placeholder

  // BLEU / ROUGE
  let bleu = 0, rouge = 0;
  try {
    bleu = safeBleu(text, [reference]);
    rouge = safeRouge(text, reference);
  } catch (err) {
    logger.warn(`World building BLEU/ROUGE error: ${(err as Error).message}`);
  }

  // ---- aggregate ----
  const rawScore =
    baseScore +
    completenessScore +
    consistencyScoreVal +
    detailScore +
    creativityScore +
    realismScore +
    depthScore +
    terminologyScore +
    narrativeScore +
    0.05 * bleu +
    0.05 * rouge;

  // ---- sanity clamp ----
  const finalScore = Math.min(Math.max(rawScore, minScore), maxScore);

  return {
    score: finalScore,
    breakdown: {
      baseScore,
      completeness: completenessScore,
      consistency: consistencyScoreVal,
      detail: detailScore,
      creativity: creativityScore,
      realism: realismScore,
      depth: depthScore,
      terminology: terminologyScore,
      narrative: narrativeScore,
      bleu,
      rouge
    }
  };
}
```

> **Note** – this file contains *only pure functions* that never touch the network or the logger except for the small error‑logging helper.  
> Unit‑tests can now feed it any string you like and assert that the returned `breakdown` matches the expected value.

### 3.3 `worldBuildingBenchmark.ts` (public API)

```ts
// worldBuildingBenchmark.ts
import { WORLD_BUILDING_CONFIG } from './config';
import { callModelAPI } from '../benchmarkUtils';
import { computeWorldBuildingScore } from './worldBuildingUtils';
import { logger } from 'shared/logging/logger';

/**
 * Public entry point used by the CI‑pipeline.
 * @returns An object that contains the final score **and** the per‑category breakdown.
 */
export async function evaluateWorldBuildingBenchmark(
  timeoutMs: number = 30000
): Promise<WorldBuildingScore> {
  const { defaultPrompt } = WORLD_BUILDING_CONFIG;

  // 1️⃣  Ask the model
  let output: string;
  try {
    output = await callModelAPI({
      prompt: defaultPrompt,
      timeoutMs
    });
  } catch (err) {
    logger.warn(`WorldBuilding: model call failed – ${(err as Error).message}`);
    throw err;                     // let the caller decide how to handle a missing run
  }

  // 2️⃣  Run the pure scoring engine
  const result = computeWorldBuildingScore(output);

  // 3️⃣  Optionally apply the *missing‑name* or *contradiction* post‑processing
  // (you can keep the old `if (!/Haven Prime/i.test(output)) { … }` logic here if you want
  // or move it into `computeWorldBuildingScore` as an extra rule).

  return result;
}
```

> **Why this is great**  
> * `callModelAPI` is still a single‑line call – the rest of the file is pure.  
> * All weights live in one place.  
> * The function signature tells the caller that *breakdown* is available.  
> * Logging is now a single call with a tag – `logger.warn('worldBuilding', …)`.

---

## 4.  Things you can tweak next

| Feature | Where to put it | Why it matters |
|---------|-----------------|----------------|
| **Unit‑tests for each rule** | `worldBuildingUtils.test.ts` | 100 % confidence that a change in a regex does not silently break the benchmark. |
| **Open‑API spec** | Add an OpenAPI definition for the benchmark API. | Teams that consume the endpoint get a typed client. |
| **Diagnostic export** | Write the `breakdown` to a JSON file when a score < 0.5. | Makes it trivial to surface a “why‑did‑this fail” story in a CI dashboard. |

---

## 5.  Bottom line

*There’s a lot of repeated “if‑regex‑test” boilerplate and magic numbers.  
By making the scoring rules data‑driven, extracting I/O from the pure logic, and returning a structured score object you’ll get:*

* **Easier to add new rules or change weights** – just edit the config.  
* **Cleaner unit‑tests** – `computeWorldBuildingScore()` can be called with any string.  
* **Better diagnostics** – callers can see exactly which category caused the low score.  
* **Consistent error handling & logging** – failures stay visible.

If you prefer a more incremental approach, you can keep the “inline” implementation for the *few* rules that need bespoke logic (e.g., the narrative part) and only refactor the repetitive parts.  
Either way, the ideas above will make the benchmark easier to maintain as the product grows.

