 *   retrieved node.
 *
 * @example
 * const node = await createAggregatedAIModelNode({
 *   modelId: 'gpt-4',
 *   aggregatedMetrics: { accuracy: 0.96, latency: 120 },
 *   metadata: { owner: 'alice', department: 'R&D' },
 * });
 * console.log(node.title); // "Aggregated Metrics for gpt-4"
 */
export async function createAggregatedAIModelNode(
  modelData: {
    modelId: string;
    aggregatedMetrics: Record<string, any>;
    metadata: Record<string, any>;
  }
): Promise<Node> {
