```ts
import { ensureNode } from 'shared/node/nodeService.js';
import { Node } from 'shared/types/index.js';

/**
 * Creates “model‑performance” nodes for a collection of model‑performance
 * data. Each node is stored in the persistence layer via {@link ensureNode}
 * and the resulting node objects are returned in the same order as the
 * input array.
 *
 * @example
 * ```ts
 * const performances = [
 *   { modelId: 'abc', performance: 0.92, metadata: { dataset: 'X' } },
 *   { modelId: 'def', performance: 0.88, metadata: { dataset: 'Y' } },
 * ];
 * const nodes = await createModelPerformanceNodes(performances);
 * console.log(nodes[0].title); // "Performance for abc"
 * ```
 *
 * @param performances An array of objects, each describing a model’s
 *   performance.  Each object must contain:
 *   - `modelId`: The identifier of the model.
 *   - `performance`: The numeric performance score.
 *   - `metadata`: An arbitrary key/value map that will be merged with the
 *     performance value when creating the node.
 *
 * @returns A promise that resolves to an array of {@link Node} objects
 *   representing the newly created nodes.  The array is ordered exactly
 *   as the input `performances` array.
 */
export async function createModelPerformanceNodes(
  performances: Array<{
    modelId: string;
    performance: number;
    metadata: Record<string, any>;
  }>
): Promise<Node[]> {
  const nodes: Node[] = [];

  for (const performance of performances) {
    const node = await ensureNode({
      type: 'model-performance',
      title: `Performance for ${performance.modelId}`,
      metadata: { performance: performance.performance, ...performance.metadata },
    });
    nodes.push(node);
  }

  return nodes;
}
```

This block keeps the original intent intact but adds a usage example, clarifies the shape of the `performances` parameter, and notes the order of the returned array.

