## Suggested refactored structure

```ts
// storageConfig.ts
import path from 'path';
import { fileURLToPath } from 'url';

const __filename = fileURLToPath(import.meta.url);
const __dirname = path.dirname(__filename);

export const BENCHMARKS_FILE = path.resolve(__dirname, 'model-benchmarks.json');
export const BENCHMARKS_FILE_PATH = BENCHMARKS_FILE;

// modelBenchmarkStore.ts
import { promises as fs } from 'fs/promises';
import { BENCHMARKS_FILE } from './storageConfig.js';
import { ModelQualityBenchmarks } from 'shared/types/aiQualityBenchmark.js';

export interface ModelBenchmarkStore {
  /** Return all benchmarks. */
  getAll(): Promise<ModelQualityBenchmarks[]>;
  /** Return a single benchmark by its modelId, or undefined. */
  getById(id: string): Promise<ModelQualityBenchmarks | undefined>;
  /** Persist a benchmark (upsert). */
  save(benchmark: ModelQualityBenchmarks): Promise<void>;
  /** Remove a benchmark. */
  delete(id: string): Promise<void>;
  /** Clear the in‑memory cache (useful for tests). */
  clearCache?(): void;
}

class FileBasedStore implements ModelBenchmarkStore {
  private _store: Record<string, ModelQualityBenchmarks> | null = null;
  private readonly file = BENCHMARKS_FILE;

  /** Lazy‑load the JSON file, creating an empty store if the file is missing. */
  private async load(): Promise<Record<string, ModelQualityBenchmarks>> {
    if (this._store !== null) return this._store;
    try {
      const data = await fs.readFile(this.file, 'utf-8');
      this._store = JSON.parse(data);
    } catch (e: any) {
      if (e.code === 'ENOENT') {
        this._store = {};
      } else if (e instanceof SyntaxError) {
        throw new Error(`Malformed benchmark file ${this.file}: ${e.message}`);
      } else {
        throw e;
      }
    }
    return this._store;
  }

  /** Persist the current in‑memory store to disk. */
  private async persist(): Promise<void> {
    if (this._store === null) return;
    // Ensure directory exists
    await fs.mkdir(path.dirname(this.file), { recursive: true });
    await fs.writeFile(this.file, JSON.stringify(this._store, null, 2), 'utf-8');
  }

  async getAll(): Promise<ModelQualityBenchmarks[]> {
    const store = await this.load();
    return Object.values(store);
  }

  async getById(id: string): Promise<ModelQualityBenchmarks | undefined> {
    const store = await this.load();
    return store[id];
  }

  async save(benchmark: ModelQualityBenchmarks): Promise<void> {
    const store = await this.load();
    store[benchmark.modelId] = benchmark;
    await this.persist();
  }

  async delete(id: string): Promise<void> {
    const store = await this.load();
    delete store[id];
    await this.persist();
  }

  clearCache() {
    this._store = null;
  }
}

/** The default store used throughout the codebase. */
export const fileBasedStore: ModelBenchmarkStore = new FileBasedStore();

// public façade – the file‑I/O details are hidden
export const {
  getAll,
  getById,
  save,
  delete: deleteBenchmark,
} = fileBasedStore;

// Additional helpers that keep the public API tiny
export async function getAllModelBenchmarks(): Promise<ModelQualityBenchmarks[]> {
  return fileBasedStore.getAll();
}

export async function getModelBenchmarkById(id: string): Promise<ModelQualityBenchmarks | undefined> {
  return fileBasedStore.getById(id);
}

export async function saveModelBenchmark(benchmark: ModelQualityBenchmarks): Promise<void> {
  return fileBasedStore.save(benchmark);
}

export async function deleteModelBenchmark(id: string): Promise<void> {
  return fileBasedStore.delete(id);
}
```

---

## Why you should consider the refactor

| Benefit | Example |
|---------|---------|
| **Single source of truth for paths** | `storageConfig.BENCHMARKS_FILE` can be overridden in a test by `jest.mock('./storageConfig.js', () => ({ BENCHMARKS_FILE: '/tmp/benchmarks.json' }))`. |
| **Pluggable storage** | If you later need to read from DynamoDB you can implement `ModelBenchmarkStore` again without touching any consumer. |
| **Cleaner public API** | Callers read the JSDoc and know the exact contract (`save(benchmark)` vs `save(benchmarks[])`). |
| **Improved error handling** | A malformed JSON file now surfaces as `Error: Malformed benchmark file …` instead of a silent `SyntaxError`. |
| **Reduced I/O** | In-memory cache avoids a write on every `getAll()` in high‑frequency scenarios. |
| **Testability** | `clearCache()` and the `resetBenchmarksFile()` helper let tests run against a fresh file each time without resorting to `fs.unlink`/`rm -rf`. |

---

### Bottom line

If you’re only going to keep this tiny module and you’re comfortable with the current API, **no refactor is “required”**.  
However, the changes above:

1. make the intent crystal‑clear (singular vs. plural, “byId” helpers),  
2. isolate concerns (I/O vs. domain logic), and  
3. give you a future‑proof hook to swap in a proper database implementation when the app grows.

Feel free to cherry‑pick the changes that fit your release cadence – the module will still compile and run, but it will be easier to understand and evolve. Happy coding!

