// ai-server/benchmarking/db/modelBenchmarksDb.ts
// ===================================================
// Persistent file‑based storage for model benchmarks.
// ----------------------------------------------
// In environments where a real database is unavailable this module
// keeps benchmark data in a JSON file (`model-benchmarks.json`) that
// lives next to this source file.
//
// The file format is a simple object where each key is a `modelId`
// and the value is a `ModelQualityBenchmarks` instance.  All
// operations are async and use Node's `fs.promises` API.
//
// ---------------------------------------------------

import { ModelQualityBenchmarks } from 'shared/types/aiQualityBenchmark.js';
import { promises as fs } from 'fs';
import path from 'path';
import { fileURLToPath } from 'url';

/**
 * Absolute path to the JSON file that stores the benchmarks.
 * The file is created lazily on first write.
 */
const __filename = fileURLToPath(import.meta.url);
const __dirname = path.dirname(__filename);
const BENCHMARKS_FILE = path.resolve(__dirname, 'model-benchmarks.json');

/**
 * Reads the entire benchmark store from disk.
 *
 * @returns {Promise<Record<string, ModelQualityBenchmarks>>}
 *   A map from `modelId` to the corresponding benchmark.
 * @throws {Error}
 *   If the file exists but cannot be read or contains invalid JSON.
 *   If any other filesystem error occurs.
 *
 * @internal
 */
async function readBenchmarksFile(): Promise<Record<string, ModelQualityBenchmarks>> {
    try {
        const data = await fs.readFile(BENCHMARKS_FILE, 'utf-8');
        return JSON.parse(data);
    } catch (err) {
        // `ENOENT` means the file does not yet exist – we treat that as an empty store.
        if ((err as NodeJS.ErrnoException).code === 'ENOENT') return {};
        throw err;
    }
}

/**
 * Writes the entire benchmark store to disk.
 *
 * @param {Record<string, ModelQualityBenchmarks>} store
 *   The full map of benchmarks to persist.
 * @returns {Promise<void>}
 *
 * @internal
 */
async function writeBenchmarksFile(store: Record<string, ModelQualityBenchmarks>): Promise<void> {
    await fs.writeFile(BENCHMARKS_FILE, JSON.stringify(store, null, 2), 'utf-8');
}

/**
 * Retrieves all stored model benchmarks.
 *
 * @returns {Promise<ModelQualityBenchmarks[]>}
 *   An array of benchmark objects.  The order is not guaranteed.
 *
 * @example
 * const benchmarks = await getModelBenchmarks();
 * console.log(benchmarks.length);
 */
export async function getModelBenchmarks(): Promise<ModelQualityBenchmarks[]> {
    const store = await readBenchmarksFile();
    return Object.values(store);
}

/**
 * Persists a single benchmark.  If a benchmark with the same `modelId`
 * already exists it will be overwritten.
 *
 * @param {ModelQualityBenchmarks} benchmark
 *   The benchmark to store.
 * @returns {Promise<void>}
 *
 * @example
 * await saveModelBenchmarks({
 *   modelId: 'gpt-4',
 *   accuracy: 0.93,
 *   latencyMs: 120,
 *   // …other properties
 * });
 */
export async function saveModelBenchmarks(benchmark: ModelQualityBenchmarks): Promise<void> {
    const store = await readBenchmarksFile();
    store[benchmark.modelId] = benchmark;
    await writeBenchmarksFile(store);
}
