## A cleaned‑up `RegisterAIModelHandler` class

```ts
import {
  IHandler,
  Context,
  Service,
  Logger,
  Node,
  Relation,
  Resource,
  KubeApi,
  NodeType,
  ResourceRelationType,
} from '@kubernetes-operators/core';
import { Container, KubeAPIClient, Label, Payload, Result } from '@kubernetes-operators/types';
import { NodeInfo } from '@kubernetes-operators/types';
import { Cluster, NodeGroup, Node, Pod, Container } from '@kubernetes-operators/types';
import { AIModel } from '@kubernetes-operators/types';
import { Performance } from '@kubernetes-operators/types';
import { Serverless } from '@kubernetes-operators/types';
import { PersistentVolumeClaim } from '@kubernetes-operators/types';
import { ConfigMap } from '@kubernetes-operators/types';
import { Secret } from '@kubernetes-operators/types';
import { Service as ServiceResource } from '@kubernetes-operators/types';
import { AIModel } from '@kubernetes-operators/types';
import { Performance } from '@kubernetes-operators/types';
import { Serverless } from '@kubernetes-operators/types';
import { PersistentVolumeClaim } from '@kubernetes-operators/types';
import { ConfigMap } from '@kubernetes-operators/types';
import { Secret } from '@kubernetes-operators/types';
import { Service } from '@kubernetes-operators/types';

/**
 * Main entry‑point for the `RegisterAIModel` operator.
 * All duplicated helpers have been collapsed into a single implementation.
 */
export class RegisterAIModelHandler implements IHandler {
  /* ------------------------------------------------------------------ */
  /* 1️⃣  Orchestration – public entry point                           */
  /* ------------------------------------------------------------------ */
  async run(payload: any, context: Context): Promise<any> {
    // 1. Fetch the cluster, node‑group, node, pod & container (if any)
    const cluster = await this.fetchCluster(context, payload);
    const nodeGroup = await this.fetchNodeGroup(context, payload, cluster);
    const node = await this.fetchNode(context, payload);
    const pod = await this.fetchPod(context, payload);
    const container = await this.fetchContainer(context, payload, pod);

    // 2. Add the container to the pod
    pod.containers.push(container);

    // 3. Resolve all relations for the pod
    await this.resolveRelations(pod, context);

    // 4. Build the base node and its relations
    const modelNode = await this.buildNodeWithRelations(payload, context);

    // 5. Build performance & serverless nodes + their relations
    await this.buildPerformanceRelations(payload);
    await this.buildServerlessRelations(payload);

    // 6. Merge performance / serverless info into the node
    const performanceNode = await this.buildPerformanceNode(payload);
    const serverlessNode   = await this.buildServerlessNode(payload);

    // 7. Persist the updated node (cluster, node‑group, node, pod, container, etc.)
    await this.updateNodeMetadata(
      modelNode,
      performanceNode,
      serverlessNode
    );

    // 8. Return the updated model node
    return modelNode;
  }

  /* ------------------------------------------------------------------ */
  /* 2️⃣  Helpers to fetch nodes by title                              */
  /* ------------------------------------------------------------------ */
  private async findPerformanceNode(payload: any): Promise<Node | null> {
    const nodeInfo = await this.fetchNodeInfo(payload);
    const performanceNode = nodeInfo?.performance;
    return performanceNode ? this.fetchNodeByTitle(Performance, performanceNode.name) : null;
  }

  private async findServerlessNode(payload: any): Promise<Node | null> {
    const nodeInfo = await this.fetchNodeInfo(payload);
    const serverlessNode = nodeInfo?.serverless;
    return serverlessNode ? this.fetchNodeByTitle(Serverless, serverlessNode.name) : null;
  }

  private async findNodeByTitle(type: string, title: string): Promise<Node | null> {
    try {
      const res = await Resource.get<Node>(context, {
        type: type as NodeType,
        title,
      });
      return res.data || null;
    } catch (e: any) {
      Logger.info(`No ${type} node with title ${title} found`);
      return null;
    }
  }

  /* ------------------------------------------------------------------ */
  /* 3️⃣  Build the “with relations” node – the core of the handler   */
  /* ------------------------------------------------------------------ */
  private async buildNodeWithRelations(payload: any, context: Context): Promise<Node> {
    const cluster       = await this.fetchCluster(context, payload);
    const nodeGroup     = await this.fetchNodeGroup(context, payload, cluster);
    const node          = await this.fetchNode(context, payload);
    const pod           = await this.fetchPod(context, payload);
    const container     = await this.fetchContainer(context, payload, pod);
    const configMap     = await this.fetchConfigMap(context, payload);
    const secret        = await this.fetchSecret(context, payload);
    const pvc           = await this.fetchPersistentVolumeClaim(context, payload);
    const service       = await this.fetchService(context, payload);

    // Base node – the AI model
    const nodeData = {
      title: payload.aiModelName,
      type: AIModel,
      metadata: {
        ...payload,
        cluster,
        nodeGroup,
        node,
        pod,
        container,
        configMap,
        secret,
        pvc,
        service,
        // These will be added later
        performance: null,
        serverless: null,
      },
    };
    return Node.merge(nodeData);
  }

  /* ------------------------------------------------------------------ */
  /* 4️⃣  Build relations for performance & serverless nodes           */
  /* ------------------------------------------------------------------ */
  private async buildPerformanceRelations(payload: any): Promise<void> {
    const performanceNode = await this.buildPerformanceNode(payload);
    if (!performanceNode) return;

    // Create/ensure the performance relation on the main node
    await this.registerPerformanceRelation(performanceNode, performanceNode);

    // Attach the performance node to the main node (via its own relation)
    const mainNode = await this.fetchNodeByTitle(AIModel, payload.aiModelName);
    if (mainNode) {
      mainNode.relations = [...(mainNode.relations || []), { target: performanceNode.title, type: ResourceRelationType.PERFORMANCE }];
      await this.updateNodeMetadata(mainNode, performanceNode, null);
    }
  }

  private async buildServerlessRelations(payload: any): Promise<void> {
    const serverlessNode = await this.buildServerlessNode(payload);
    if (!serverlessNode) return;

    await this.registerServerlessRelation(serverlessNode, serverlessNode);

    const mainNode = await this.fetchNodeByTitle(AIModel, payload.aiModelName);
    if (mainNode) {
      mainNode.relations = [...(mainNode.relations || []), { target: serverlessNode.title, type: ResourceRelationType.SERVERLESS }];
      await this.updateNodeMetadata(mainNode, null, serverlessNode);
    }
  }

  /* ------------------------------------------------------------------ */
  /* 5️⃣  Build / merge the performance / serverless nodes             */
  /* ------------------------------------------------------------------ */
  private async buildPerformanceNode(payload: any): Promise<Node | null> {
    const performance = await this.fetchPerformance(context, payload);
    if (!performance) return null;

    const node = await this.fetchNodeByTitle(Performance, performance.name);
    return node
      ? Node.merge({
          ...node,
          title: performance.name,
          metadata: { ...node.metadata, ...performance },
        })
      : Node.create({
          title: performance.name,
          type: Performance,
          metadata: performance,
          relations: [{ target: 'AI Model', type: ResourceRelationType.PERFORMANCE }],
        });
  }

  private async buildServerlessNode(payload: any): Promise<Node | null> {
    const serverless = await this.fetchServerless(context, payload);
    if (!serverless) return null;

    const node = await this.fetchNodeByTitle(Serverless, serverless.name);
    return node
      ? Node.merge({
          ...node,
          title: serverless.name,
          metadata: { ...node.metadata, ...serverless },
        })
      : Node.create({
          title: serverless.name,
          type: Serverless,
          metadata: serverless,
          relations: [{ target: 'AI Model', type: ResourceRelationType.SERVERLESS }],
        });
  }

  /* ------------------------------------------------------------------ */
  /* 6️⃣  Persist the updated metadata of a node                       */
  /* ------------------------------------------------------------------ */
  private async updateNodeMetadata(
    modelNode: Node,
    performanceNode: Node | null,
    serverlessNode: Node | null
  ) {
    const node = await this.fetchNodeByTitle(AIModel, modelNode.title);
    if (!node) return;

    // Merge performance / serverless info if they exist
    const merged = Node.merge({
      ...node,
      title: modelNode.title,
      metadata: {
        ...node.metadata,
        ...modelNode.metadata,
        ...(performanceNode ? { performance: performanceNode.metadata } : {}),
        ...(serverlessNode ? { serverless: serverlessNode.metadata } : {}),
      },
    });

    // Write back to storage
    await Resource.create(context, {
      data: merged,
    });
  }

  /* ------------------------------------------------------------------ */
  /* 7️⃣  Generic relation helpers (create / update)                   */
  /* ------------------------------------------------------------------ */
  private async ensureRelation(node: Node, targetTitle: string, type: ResourceRelationType) {
    const existing = node.relations?.find((r) => r.target === targetTitle && r.type === type);
    if (!existing) {
      node.relations = [...(node.relations || []), { target: targetTitle, type }];
    }
  }

  private async createRelationIfMissing(node: Node, target: Node, type: ResourceRelationType) {
    await this.ensureRelation(node, target.title, type);
  }

  private async registerPerformanceRelation(performanceNode: Node, mainNode: Node) {
    await this.createRelationIfMissing(mainNode, performanceNode, ResourceRelationType.PERFORMANCE);
  }

  private async registerServerlessRelation(serverlessNode: Node, mainNode: Node) {
    await this.createRelationIfMissing(mainNode, serverlessNode, ResourceRelationType.SERVERLESS);
  }

  /* ------------------------------------------------------------------ */
  /* 8️⃣  Resolve additional relations on a pod (config‑map, secret, …)*/
  /* ------------------------------------------------------------------ */
  private async resolveRelations(pod: Pod, context: Context) {
    const cm    = await this.fetchConfigMap(context, pod);
    const secret= await this.fetchSecret(context, pod);
    const pvc   = await this.fetchPersistentVolumeClaim(context, pod);
    const svc   = await this.fetchService(context, pod);

    pod.relations = [
      { target: cm?.name,   type: ResourceRelationType.CONFIG_MAP },
      { target: secret?.name, type: ResourceRelationType.SECRET },
      { target: pvc?.name,  type: ResourceRelationType.PVC },
      { target: svc?.name,  type: ResourceRelationType.SERVICE },
    ].filter((r) => r.target);
  }

  /* ------------------------------------------------------------------ */
  /* 9️⃣  Fetch‑implementations (cluster, node‑group, node, …)         */
  /* ------------------------------------------------------------------ */
  // These would normally delegate to the `KubeAPIClient` helpers.
  // They’re omitted here for brevity – keep the original implementations.
  // Example:
  private async fetchCluster(context: Context, payload: any) { /* ... */ }
  private async fetchNodeGroup(context: Context, payload: any, cluster: any) { /* ... */ }
  private async fetchNode(context: Context, payload: any) { /* ... */ }
  private async fetchPod(context: Context, payload: any) { /* ... */ }
