// -----------------------------------------------------------------------------
// ModelCommunityMembershipAnalyzer
// -----------------------------------------------------------------------------

import { ensureNode, ensureNodes, ensureEdges, getNodes } from './db';
import { Component, Node, Edge, Relation } from './types';

/**
 * A comprehensive component that:
 * 1. Reads `ai-model` nodes and their benchmark data.
 * 2. Builds a similarity graph based on model family, benchmark scores, and capabilities.
 * 3. Computes community metrics (rank, cluster affinity, etc.).
 * 4. Updates the node metadata with the community membership data.
 */
export class ModelCommunityMembershipAnalyzer extends Component {
    /**
     * Analyzes each model node and updates its community membership.
     * @param data Optional data structure containing benchmark results
     *              and edges (to skip DB queries if already loaded).
     */
    async analyzeAndPopulateCommunity(
        data: {
            models?: Node[];
            performances?: Node[];
            edges?: Edge[];
        } = {}
    ): Promise<void> {
        // ---------------------------------------------------------------------
        // 0. Load data from the database if not supplied
        // ---------------------------------------------------------------------
        const [models, performances, edges] = await Promise.all([
            data.models ?? getNodes('ai-model'),
            data.performances ?? getNodes('ai-model-performance'),
            data.edges ?? getNodes('ai-model-performance')
        ]);

        // Map nodes by unique title for quick look‑ups
        const modelMap = new Map<string, Node>();
        const perfMap = new Map<string, Node>();
        const edgeMap = new Map<string, Edge>();

        models.forEach(n => modelMap.set(n.title, n));
        performances.forEach(n => perfMap.set(n.title, n));
        edges.forEach(e => edgeMap.set(`${e.from}-${e.to}-${e.title}`, e));

        // ---------------------------------------------------------------------
        // 1. Build a list of all relevant nodes:
        //    - AI models
        //    - Performance nodes (the benchmark results)
        //    - Edge nodes (relationships between models and performance)
        // ---------------------------------------------------------------------
        const aiModelNodes = Array.from(modelMap.values());
        const performanceNodes = Array.from(perfMap.values());
        const edgeNodes = Array.from(edgeMap.values());

        // ---------------------------------------------------------------------
        // 2. Build a graph representation
        //    - Nodes: all ai-model, ai-model-performance, and edge nodes
        //    - Edges: from ai-model -> edge -> ai-model-performance
        // ---------------------------------------------------------------------
        const graphNodes: Node[] = [...aiModelNodes, ...performanceNodes, ...edgeNodes];
        const graphEdges: Edge[] = [];

        // Create edges for the graph: ai-model -> edge -> performance
        aiModelNodes.forEach(model => {
            const relatedEdges = edgeNodes.filter(
                e => e.from === model.title || e.to === model.title
            );
            relatedEdges.forEach(e => {
                graphEdges.push(e);
            });
        });

        // ---------------------------------------------------------------------
        // 3. Compute similarity between AI models
        // ---------------------------------------------------------------------
        const similarities = await this.computeSimilarityGraph(
            aiModelNodes,
            performanceNodes
        );

        // ---------------------------------------------------------------------
        // 4. Update each AI model node with the community membership data
        // ---------------------------------------------------------------------
        for (const modelNode of aiModelNodes) {
            await this.updateModelCommunityMetadata(
                modelNode,
                similarities[modelNode.title] ?? []
            );
        }

        // ---------------------------------------------------------------------
        // 5. Persist all nodes, edges, and relations in the DB
        // ---------------------------------------------------------------------
        await Promise.all([
            ensureNodes(graphNodes),
            ensureEdges(graphEdges),
            ensureEdges(
                this.createCommunityRelations(aiModelNodes, similarities)
            )
        ]);
    }

    /* --------------------------------------------------------------------- */
    /* --------------------------------------------------------------------- */

    /**
     * Builds the similarity graph for AI models.
     * Returns a map `modelTitle => Array<similar model titles>`
     */
    private async computeSimilarityGraph(
        aiModels: Node[],
        performances: Node[]
    ): Promise<Record<string, Node[]>> {
        const modelPerformances: Record<string, any> = {};

        // Map each model → its performance nodes
        aiModels.forEach(model => {
            const perfIds: string[] = (model.relationships?.performanceIds ?? []) as string[];
            perfIds.forEach(pid => {
                const perfNode = performances.find(p => p.title === pid);
                if (perfNode) {
                    modelPerformances[model.title] =
                        modelPerformances[model.title] ?? [];
                    modelPerformances[model.title].push(perfNode);
                }
            });
        });

        // Compute similarity pairs
        const similarities: Record<string, Node[]> = {};

        for (const [titleA, nodeA] of Object.entries(modelPerformances)) {
            similarities[titleA] = [];
            for (const [titleB, nodeB] of Object.entries(modelPerformances)) {
                if (titleA === titleB) continue;
                const similarityScore = await this.computeSimilarityBetweenModels(
                    nodeA,
                    nodeB
                );
                if (similarityScore > 0.7) {
                    similarities[titleA].push(nodeB);
                }
            }
        }

        return similarities;
    }

    /* --------------------------------------------------------------------- */

    /**
     * Computes similarity between two AI models.
     * Considers:
     *  - Same or similar family
     *  - Overlap in benchmark results
     *  - Similar performance metrics
     */
    private async computeSimilarityBetweenModels(
        modelA: Node,
        modelB: Node
    ): Promise<number> {
        const familyA = this.extractFamily(modelA);
        const familyB = this.extractFamily(modelB);

        // Similarity from family
        const familySim = familyA === familyB ? 1 : 0;

        // Similarity from benchmark metrics
        const metricSim = this.compareMetrics(
            modelA?.metadata?.benchmarks ?? {},
            modelB?.metadata?.benchmarks ?? {}
        );

        // Similarity from capabilities
        const capabilitySim = this.compareCapabilities(
            modelA?.metadata?.capabilities ?? [],
            modelB?.metadata?.capabilities ?? []
        );

        // Weighted combination (weights can be tuned)
        const weightFamily = 0.4;
        const weightMetrics = 0.3;
        const weightCapability = 0.3;

        return (
            weightFamily * familySim +
            weightMetrics * metricSim +
            weightCapability * capabilitySim
        );
    }

    /* --------------------------------------------------------------------- */

    /**
     * Helper to extract the model family string from an AI model node.
     */
    private extractFamily(model: Node): string {
        const family = (model.metadata as any)?.family as string;
        return family?.trim().toLowerCase() ?? '';
    }

    /* --------------------------------------------------------------------- */

    /**
     * Helper to compare benchmark metric objects.
     * The similarity is the fraction of identical key/value pairs.
     */
    private compareMetrics(
        metricsA: Record<string, number>,
        metricsB: Record<string, number>
    ): number {
        const keysA = Object.keys(metricsA);
        const keysB = Object.keys(metricsB);
        const common = keysA.filter(k => keysB.includes(k));
        if (common.length === 0) return 0;
        const matching = common.filter(k => metricsA[k] === metricsB[k]);
        return matching.length / common.length;
    }

    /* --------------------------------------------------------------------- */

    /**
     * Helper to compare model capabilities.
     * The similarity is the fraction of common capabilities.
     */
    private compareCapabilities(
        capsA: string[],
        capsB: string[]
    ): number {
        if (!capsA?.length || !capsB?.length) return 0;
        const setA = new Set(capsA.map(c => c.toLowerCase().trim()));
        const setB = new Set(capsB.map(c => c.toLowerCase().trim()));
        const intersection = [...setA].filter(v => setB.has(v));
        return intersection.length / Math.max(setA.size, setB.size);
    }

    /* --------------------------------------------------------------------- */

    /**
     * Computes the similarity graph for a list of AI models and
     * their performance nodes.
     */
    private async computeSimilarityGraph(
        aiModelNodes: Node[],
        performanceNodes: Node[]
    ): Promise<Record<string, Node[]>> {
        const similarityGraph: Record<string, Node[]> = {};

        aiModelNodes.forEach(model => {
            similarityGraph[model.title] = [];
            aiModelNodes.forEach(other => {
                if (model.title === other.title) return;

                const similarity = this.computeModelSimilarity(
                    model,
                    other,
                    performanceNodes
                );

                if (similarity > 0.7) {
                    similarityGraph[model.title].push(other);
                }
            });
        });

        return similarityGraph;
    }

    /* --------------------------------------------------------------------- */

    /**
     * Computes similarity between two models, taking into account:
     *  - Family similarity
     *  - Benchmark metric similarity
     *  - Capability similarity
     */
    private computeModelSimilarity(
        modelA: Node,
        modelB: Node,
        performanceNodes: Node[]
    ): number {
        const familyA = this.extractFamily(modelA);
        const familyB = this.extractFamily(modelB);

        // Family similarity: 1 if same family, 0 otherwise
        const familySim = familyA === familyB ? 1 : 0;

        // Benchmark metric similarity
        const perfA = this.getPerformanceForModel(
            modelA,
            performanceNodes
        );
        const perfB = this.getPerformanceForModel(
            modelB,
            performanceNodes
        );
        const metricSim = this.compareMetrics(
            perfA?.metadata?.benchmarks ?? {},
            perfB?.metadata?.benchmarks ?? {}
        );

        // Capability similarity
        const capSim = this.compareCapabilities(
            modelA?.metadata?.capabilities ?? [],
            modelB?.metadata?.capabilities ?? []
        );

        // Weighted combination
        const weightFamily = 0.4;
        const weightMetrics = 0.3;
        const weightCapability = 0.3;

        return (
            weightFamily * familySim +
            weightMetrics * metricSim +
            weightCapability * capSim
        );
    }

    /* --------------------------------------------------------------------- */

    /**
     * Retrieves the `ai-model-performance` node that belongs to a given
     * AI model node.
     */
    private getPerformanceForModel(
        modelNode: Node,
        performanceNodes: Node[]
    ): Node | undefined {
        return performanceNodes.find(
            perf => perf.relationships?.modelId === modelNode.id
        );
    }

    /* --------------------------------------------------------------------- */

    /**
     * Computes the community membership data for a single AI model.
     * Returns an array of similarity edges to other models.
     */
    private async updateModelCommunityMetadata(
        modelNode: Node,
        similarityEdges: Node[]
    ): Promise<void> {
        // Compute community metrics
        const communityRank = this.calculateCommunityRank(similarityEdges);
        const clusterAffinity = this.calculateClusterAffinity(similarityEdges);

        // Build the community metadata
        const communityMembership: Record<string, any> = {
            rank: communityRank,
            affinity: clusterAffinity,
            similarModels: similarityEdges.map(e => e.to)
        };

        // Persist the updated node
        await ensureNode({
            ...modelNode,
            metadata: {
                ...(modelNode.metadata ?? {}),
                communityMembership
            }
        });
    }

    /* --------------------------------------------------------------------- */

    /**
     * Calculates an overall community rank for a model.
     * A simple metric: the average similarity score to all other models.
     */
    private calculateCommunityRank(similarityEdges: Node[]): number {
        if (!similarityEdges.length) return 0;
        const scores = similarityEdges.map(e => e.relationships?.similarity ?? 0);
        const total = scores.reduce((s, c) => s + c, 0);
        return total / scores.length;
    }

    /* --------------------------------------------------------------------- */

    /**
     * Calculates cluster affinity for a model.
     * For this example we simply return the number of unique families
     * that the model is similar to.
     */
    private calculateClusterAffinity(similarityEdges: Node[]): number {
        const families = new Set<string>();
        similarityEdges.forEach(e => {
            const otherModel = (e.metadata as any)?.otherModelFamily as string;
            if (otherModel) families.add(otherModel);
        });
        return families.size;
    }

    /* --------------------------------------------------------------------- */

    /**
     * Utility: Categorises a model into a size bucket.
     * Used for ranking/affinity adjustments if desired.
     */
    private categorizeModelSize(modelId: string): string {
        return 'medium'; // Default
    }
}
