/* -------------  Input/Output interfaces ------------- */
export interface GetSimilarModelsInput {
  /** The title/id of the model that will be enriched */
  currentModel: string;
  /** Optional tags already present on the model */
  tags?: string[];
  /** Minimum parameter count (in billions) for candidates */
  minParamCount?: number;
  /** Maximum parameter count (in billions) for candidates */
  maxParamCount?: number;
  /** Number of top similar models to return */
  topN?: number;
}

export interface SimilarModel {
  /** Title/id of the similar model */
  modelId: string;
  /** Raw similarity score [0‑1] */
  similarity: number;
  /** Family or architecture group */
  family?: string;
  /** List of capabilities derived from benchmarks */
  capabilities?: string[];
}

export interface GetSimilarModelsOutput {
  /** List of similar models, sorted by descending similarity */
  similarModels: SimilarModel[];
  /** How closely the model fits into the community (0‑1) */
  communityRank: number;
  /** Affinity to each cluster (family/capability) */
  clusterAffinity: Record<string, number>;
  /** Timestamp of the enrichment */
  lastCommunityUpdate: string;
}

/* -------------  Helper utilities ------------- */
function extractParamCount(id: string): number | null {
  const m = id.match(/(\d+)(?:b|B)/);
  return m ? parseInt(m[1], 10) : null;
}

function similarityScore(a: number[], b: number[]): number {
  if (!a.length || !b.length) return 0;
  const setA = new Set(a);
  const setB = new Set(b);
  const intersection = [...setA].filter(v => setB.has(v)).length;
  const union = new Set([...setA, ...setB]).size;
  return union ? intersection / union : 0;
}

function paramDiffScore(c1: number, c2: number): number {
  const diff = Math.abs(c1 - c2);
  const maxDiff = 20;        // 20 billion difference → 0 similarity
  return diff >= maxDiff ? 0 : 1 - diff / maxDiff;
}

function familyScore(famA: string, famB: string): number {
  return famA === famB ? 0.5 : 0;
}

function capabilityScore(capA: string[] | undefined, capB: string[] | undefined): number {
  return similarityScore(capA ?? [], capB ?? []);
}

/* -------------  Main plugin function ------------- */
/**
 * Enriches an ai‑model node with community information
 * based on tags, architecture, and parameter size.
 */
export async function getSimilarModels(
  data: GetSimilarModelsInput
): Promise<GetSimilarModelsOutput> {
  /* ---- Validate input ---- */
  const {
    currentModel,
    tags = [],
    minParamCount = 1,
    maxParamCount = Infinity,
    topN = 5,
  } = data;

  if (!currentModel) throw new Error('currentModel is required');

  /* ---- 1️⃣  Load all ai‑model nodes  ---- */
  // NOTE: replace `listNodes` with the actual query API that returns an array of Nodes
  // const allNodes = await listNodes<Node>({ type: 'ai-model' });
  const allNodes: Node[] = []; // ← placeholder

  /* ---- 2️⃣  Locate the node for the current model  ---- */
  const current = allNodes.find(n => n.title?.toLowerCase() === currentModel.toLowerCase());
  if (!current) {
    throw new Error(`Model “${currentModel}” not found in the database`);
  }

  /* ---- 3️⃣  Derive family and parameter count of current model  ---- */
  const curFamily = current.properties?.family?.[0]?.value ?? current.title?.split(/[ /]/)[0];
  const curParam = extractParamCount(current.title ?? '') ?? 0;

  /* ---- 4️⃣  Compute similarity for each candidate  ---- */
  const candidates: SimilarModel[] = [];

  for (const node of allNodes) {
    // Skip self
    if (node.title?.toLowerCase() === currentModel.toLowerCase()) continue;

    const candParam = extractParamCount(node.title ?? '') ?? 0;
    if (candParam < minParamCount || candParam > maxParamCount) continue;

    const candFamily = node.properties?.family?.[0]?.value ?? node.title?.split(/[ /]/)[0];
    const candTags: string[] = node.tags?.map(t => t.trim().toLowerCase()) ?? [];
    const candCap: string[] | undefined = node.properties?.capabilities?.[0]?.value
      ? node.properties.capabilities[0].value.split(/\s*,\s*/)
      : undefined;

    // Tag overlap similarity
    const tagSim = similarityScore(tags.map(t => t.toLowerCase()), candTags);

    // Parameter‑size similarity
    const paramSim = paramDiffScore(curParam, candParam);

    // Architecture (family) bonus
    const famSim = familyScore(curFamily ?? '', candFamily ?? '');

    // Capability overlap (if available)
    const capSim = capabilityScore(candCap, []); // no counterpart for current

    // Final weighted score: tags 50 %, size 30 %, family 20 %
    const sim = 0.5 * tagSim + 0.3 * paramSim + 0.2 * famSim;

    if (sim <= 0) continue;

    candidates.push({
      modelId: node.title ?? '',
      similarity: sim,
      family: candFamily,
      capabilities: candCap,
    });
  }

  /* ---- 5️⃣  Sort and truncate to top N  ---- */
  candidates.sort((a, b) => b.similarity - a.similarity);
  const top = candidates.slice(0, topN);

  /* ---- 6️⃣  Compute community rank (average similarity)  ---- */
  const communityRank = top.reduce((s, m) => s + m.similarity, 0) / (top.length || 1);

  /* ---- 7️⃣  Compute cluster affinity  ---- */
  const affinity: Record<string, number> = {};
  top.forEach(m => {
    const fam = m.family ?? 'unknown';
    affinity[fam] = (affinity[fam] ?? 0) + m.similarity;
    if (m.capabilities) {
      m.capabilities.forEach(c => {
        affinity[`cap:${c}`] = (affinity[`cap:${c}`] ?? 0) + m.similarity;
      });
    }
  });
  // Normalize
  const sum = Object.values(affinity).reduce((a, b) => a + b, 0);
  Object.keys(affinity).forEach(k => (affinity[k] = (affinity[k] ?? 0) / (sum || 1)));

  /* ---- 8️⃣  Prepare output  ---- */
  const output: GetSimilarModelsOutput = {
    similarModels: top,
    communityRank,
    clusterAffinity: affinity,
    lastCommunityUpdate: new Date().toISOString(),
  };

  /* ---- 9️⃣  Persist enrichment back to the current node  ---- */
  // (The persistence layer depends on the platform – replace with real API)
  try {
    await ensureNode({
      type: 'ai-model',
      title: currentModel,
      properties: [
        {
          property: 'communityMembership',
          value: JSON.stringify(output),
          type: 'json',
        },
      ],
    });
  } catch (e) {
    console.warn('Could not persist enrichment:', e);
  }

  return output;
}
