Here is the complete, refined **AI Model Quality Manager** plugin.  
It aggregates quality metrics, calculates embeddings, updates the node database, and stores a rich “community membership” structure that is refreshed on demand.

```ts
/* ────────────────────────────────────────────────────────────────────── */
/*  AI Model Quality Manager – “ai-model-quality-manager”                 */
/*  Handles aggregation of model metrics, embedding creation, and         */
/*  community membership calculations.                                    */
/* ────────────────────────────────────────────────────────────────────── */

export class AiModelQualityManager {
  // --------------------------------------------------------------------
  // Public API
  // --------------------------------------------------------------------
  public async updateMetricsWithCommunity(
    modelNodes: Node[],
    aggregateResult: AggregateResult,
    forceCommunityUpdate: boolean = false
  ): Promise<void> {
    const modelIds = modelNodes.map(n => n.title);
    const aggregatedMetrics = this.getAggregatedMetrics(aggregateResult);

    // Create embedding and community data
    const similarities = await this.createEmbeddingAndCommunity(
      modelIds,
      aggregatedMetrics
    );

    // Update every model node with the new community data
    for (const [modelId, embedding] of Object.entries(similarities)) {
      await this.updateModelCommunityMetadata(
        this.findNodeByTitle(modelNodes, modelId),
        embedding
      );
    }
  }

  // --------------------------------------------------------------------
  // Core processing
  // --------------------------------------------------------------------
  public async createEmbeddingAndCommunity(
    modelIds: string[],
    aggregatedMetrics: Record<string, any>
  ): Promise<Record<string, any>> {
    const embeddings: Record<string, any> = {};

    // Process each model
    for (const modelId of modelIds) {
      const metrics = aggregatedMetrics[modelId];
      if (!metrics) continue;

      // ------------------------------------
      // 1. Performance embedding
      // ------------------------------------
      const performanceEmbedding = this.computePerformanceEmbedding(metrics);
      const embeddingKey = `${modelId}-performance-embedding`;
      embeddings[embeddingKey] = performanceEmbedding;

      // ------------------------------------
      // 2. Quality embedding
      // ------------------------------------
      const qualityEmbedding = await this.computeQualityEmbedding(
        modelId,
        metrics
      );
      embeddings[`${modelId}-quality-embedding`] = qualityEmbedding;

      // ------------------------------------
      // 3. Community embedding
      // ------------------------------------
      const communityEmbedding = await this.computeCommunityEmbedding(
        modelId,
        metrics
      );
      embeddings[`${modelId}-community-embedding`] = communityEmbedding;

      // ------------------------------------
      // 4. Store community data
      // ------------------------------------
      const communityKey = `${modelId}-community-membership`;
      embeddings[communityKey] = await this.storeCommunityData(
        modelId,
        metrics,
        communityEmbedding
      );
    }

    return embeddings;
  }

  // --------------------------------------------------------------------
  // Helpers
  // --------------------------------------------------------------------
  private findNodeByTitle(nodes: Node[], title: string): Node | undefined {
    return nodes.find(node => node.title === title);
  }

  private getAggregatedMetrics(
    aggregateResult: AggregateResult
  ): Record<string, any> {
    const aggregatedMetrics: Record<string, any> = {};

    const models = aggregateResult.aggregation
      .filter(a => a.type === 'ai-model')
      .map(a => a.title);

    const metrics = aggregateResult.aggregation
      .filter(a => a.type === 'ai-model-metric')
      .filter(a => models.includes(a.title));

    for (const metric of metrics) {
      aggregatedMetrics[metric.title] = metric.metadata;
    }

    return aggregatedMetrics;
  }

  // --------------------------------------------------------------------
  // Performance embedding
  // --------------------------------------------------------------------
  private computePerformanceEmbedding(
    metrics: Record<string, any>
  ): number[] {
    const performance: number[] = [];

    // 1. Latency (ms)
    const latency = metrics.latency?.median || metrics.latency?.avg || Infinity;
    performance.push(Math.max(0, Math.min(1, 1 - latency / 100)));

    // 2. Bandwidth (B/s)
    const bandwidth = metrics.bandwidth?.max || 0;
    performance.push(Math.max(0, Math.min(1, Math.log10(bandwidth + 1) / 5)));

    // 3. Compute cost ($/token)
    const cost = metrics.compute_cost?.min || Infinity;
    performance.push(Math.max(0, Math.min(1, 1 - cost / 0.5)));

    // 4. Memory usage (GiB)
    const memory = metrics.memory?.max || Infinity;
    performance.push(Math.max(0, Math.min(1, 1 - memory / 16)));

    return performance;
  }

  // --------------------------------------------------------------------
  // Quality embedding
  // --------------------------------------------------------------------
  private async computeQualityEmbedding(
    modelId: string,
    metrics: Record<string, any>
  ): Promise<number[]> {
    const quality: number[] = [];

    // 1. Book quality (0‑1)
    quality.push(
      Math.max(
        0,
        Math.min(
          1,
          metrics.book_quality?.overall_score ?? 0
        )
      )
    );

    // 2. Sub‑section quality (average)
    const subScores = Object.entries(metrics)
      .filter(([k]) => k.startsWith('section_'))
      .map(([, v]) => v.overall_score ?? 0);
    const subAvg =
      subScores.length > 0
        ? subScores.reduce((a, b) => a + b, 0) / subScores.length
        : 0;
    quality.push(Math.max(0, Math.min(1, subAvg)));

    // 3. Genre‑specific scores
    const genres = ['fantasy', 'sci_fi', 'historical'];
    for (const genre of genres) {
      const score = metrics[genre]?.score ?? 0;
      quality.push(Math.max(0, Math.min(1, score)));
