// scheduleNextQualityBenchmark.test.ts
import { scheduleNextQualityBenchmark, NextBenchmarkSchedule } from './scheduleNextQualityBenchmark';
import { QualityBenchmarkScore } from 'shared/types/aiQualityBenchmark.js';

describe('scheduleNextQualityBenchmark', () => {
  const baseDate = new Date('2025-01-01T00:00:00Z');

  const createScore = (score: number | null): QualityBenchmarkScore => ({
    type: 'example',
    score: score as unknown as number, // cast for test
    // other properties can be omitted
  });

  test('immediate run when no benchmarks are provided', () => {
    const result = scheduleNextQualityBenchmark([], baseDate);
    expect(result.shouldRun).toBe(true);
    expect(result.intervalDays).toBe(0);
    expect(result.nextBenchmark).toBe(baseDate.toISOString());
  });

  test('interval 1 day for avgScore >= 0.85', () => {
    const benchmarks = [
      createScore(0.9),
      createScore(0.86),
      createScore(0.85),
    ];
    const result = scheduleNextQualityBenchmark(benchmarks, baseDate);
    expect(result.intervalDays).toBe(1);
    expect(result.shouldRun).toBe(false);
    const expectedNext = new Date(baseDate.getTime() + 24 * 60 * 60 * 1000);
    expect(result.nextBenchmark).toBe(expectedNext.toISOString());
  });

  test('interval 3 days for 0.7 <= avgScore < 0.85', () => {
    const benchmarks = [
      createScore(0.8),
      createScore(0.75),
      createScore(0.7),
    ];
    const result = scheduleNextQualityBenchmark(benchmarks, baseDate);
    expect(result.intervalDays).toBe(3);
    expect(result.shouldRun).toBe(false);
    const expectedNext = new Date(baseDate.getTime() + 3 * 24 * 60 * 60 * 1000);
    expect(result.nextBenchmark).toBe(expectedNext.toISOString());
  });

  test('interval 7 days for avgScore < 0.7', () => {
    const benchmarks = [
      createScore(0.6),
      createScore(0.5),
      createScore(0.55),
    ];
    const result = scheduleNextQualityBenchmark(benchmarks, baseDate);
    expect(result.intervalDays).toBe(7);
    expect(result.shouldRun).toBe(false);
    const expectedNext = new Date(baseDate.getTime() + 7 * 24 * 60 * 60 * 1000);
    expect(result.nextBenchmark).toBe(expectedNext.toISOString());
  });

  test('shouldRun is true when now is on or after the next benchmark', () => {
    const benchmarks = [createScore(0.9)]; // avg >= 0.85 -> 1 day
    // now 1 day after the scheduled next
    const futureDate = new Date(baseDate.getTime() + 24 * 60 * 60 * 1000 + 1);
    const result = scheduleNextQualityBenchmark(benchmarks, futureDate);
    expect(result.shouldRun).toBe(true);
    // nextBenchmark should still be baseDate + 1 day
    const expectedNext = new Date(baseDate.getTime() + 24 * 60 * 60 * 1000);
    expect(result.nextBenchmark).toBe(expectedNext.toISOString());
  });

  test('shouldRun is false when now is before the next benchmark', () => {
    const benchmarks = [createScore(0.9)]; // 1 day interval
    const result = scheduleNextQualityBenchmark(benchmarks, baseDate);
    expect(result.shouldRun).toBe(false);
  });

  test('non-number scores are treated as 0', () => {
    const benchmarks = [
      { type: 'a', score: 'invalid' as unknown as number },
      { type: 'b', score: 0.9 as unknown as number },
    ];
    const result = scheduleNextQualityBenchmark(benchmarks, baseDate);
    // avg = (0 + 0.9) / 2 = 0.45 -> 7 days
    expect(result.intervalDays).toBe(7);
  });

  test('uses provided now date if given', () => {
    const customNow = new Date('2024-12-31T23:00:00Z');
    const benchmarks = [createScore(0.9)];
    const result = scheduleNextQualityBenchmark(benchmarks, customNow);
    const expectedNext = new Date(customNow.getTime() + 24 * 60 * 60 * 1000);
    expect(result.nextBenchmark).toBe(expectedNext.toISOString());
  });
});
