```ts
/* ==========================================================
   Runtime imports
   ========================================================== */
import fs from 'fs';
import path from 'path';
import fetch from 'node-fetch';
import { emitJobSSEEvent } from '@services/sse';
import { markServerUnhealthy } from '@services/serverHealth';

/* ==========================================================
   Type‑only imports
   ========================================================== */
import type { AIServer } from '@types/server';
import type { ServerModelBenchmark, ServerModelBenchmarkWithQuality } from '@types/benchmark';

interface BenchmarkJob {
  server: AIServer;
  model: string;
  key: string;           // `${server.id}:${model}`
}

class BenchmarkModule {
  /* ==========================================================
     Constants
     ========================================================== */
  private static readonly INTERVALS = {
    MULTI_SERVER: 600_000,   // 10 min
    SINGLE_SERVER: 3_000_000, // 50 min
    MIN_BACKOFF: 60_000,     // 1 min
    MAX_BACKOFF: 86_400_000  // 24 h
  };
  private static readonly TIMEOUT = 60_000; // 60 s

  /* ==========================================================
     State
     ========================================================== */
  private benchmarks   = new Map<string, ServerModelBenchmarkWithQuality>();
  private inFlight     = new Set<string>();            // `${serverId}:${model}`
  private intervalMap  = new Map<string, NodeJS.Timeout>();

  /* ----------------------------------------------------------
     Helpers
     ---------------------------------------------------------- */
  private getBenchmark(key: string) {
    return this.benchmarks.get(key);
  }

  private setBenchmark(key: string, bench: ServerModelBenchmarkWithQuality) {
    this.benchmarks.set(key, bench);
  }

  private isRamOverage(err: any): boolean {
    return err?.ramOverage || /ram|memory/i.test(err?.message ?? '');
  }

  private emitBenchmarkEvent(
    job: { key: string; state: string; error?: any; message: string }
  ): void {
    const [serverId, model] = job.key.split(':');
    emitJobSSEEvent({
      jobId: `benchmark_${serverId}_${model}_${Date.now()}`,
      sessionId: 'benchmark',
      version: 'v1',
      state: job.state,
      error: job.error,
      message: job.message
    });
  }

  /* ----------------------------------------------------------
     Decision logic
     ---------------------------------------------------------- */
  private computeInterval(job: BenchmarkJob, lastRun: number): number {
    /*   - use the “stable” interval for the server–model pair<br>
     *   - back‑off if the last run failed due to a timeout<br>
     *   - never allow the next run to be sooner than MIN_BACKOFF<br>
     */
    const base = job.server.multiple ? BenchmarkModule.INTERVALS.MULTI_SERVER
                                     : BenchmarkModule.INTERVALS.SINGLE_SERVER;
    const backoff = Math.max(
      BenchmarkModule.INTERVALS.MIN_BACKOFF,
      Math.min(base, BenchmarkModule.INTERVALS.MAX_BACKOFF)
    );
    return base + backoff; // simplistic; replace with your own rule set
  }

  private shouldRunBenchmark(job: BenchmarkJob, now: number): boolean {
    const bench = this.getBenchmark(job.key);
    if (!bench) return true;
    const interval = this.computeInterval(job, bench.lastTested ?? 0);
    return now - bench.lastTested > interval;
  }

  /* ----------------------------------------------------------
     Public API
     ---------------------------------------------------------- */
  /** Queue a single benchmark run */
  public async runJob(job: BenchmarkJob): Promise<void> {
    const now = Date.now();
    if (!this.shouldRunBenchmark(job, now)) return;

    if (this.inFlight.has(job.key)) return; // already being processed
    this.inFlight.add(job.key);

    try {
      await this.emitBenchmarkEvent({
        key: job.key,
        state: 'running',
        message: `Starting benchmark for ${job.server.id}/${job.model}`
      });

      await this.benchmarkServerModel(job.server, job.model);

      this.emitBenchmarkEvent({
        key: job.key,
        state: 'success',
        message: `Finished benchmark for ${job.server.id}/${job.model}`
      });
    } catch (err) {
      if (this.isRamOverage(err)) {
        await markServerUnhealthy(job.server.id, err);
      }
      this.emitBenchmarkEvent({
        key: job.key,
        state: 'failure',
        error: err,
        message: `Benchmark failed for ${job.server.id}/${job.model}`
      });
    } finally {
      this.inFlight.delete(job.key);
    }
  }

  /** Schedule next run for all servers */
  public async maybeAll(): Promise<void> {
    const jobs: BenchmarkJob[] = [];
    for (const server of this.servers.values()) {
      for (const model of server.models) {
        jobs.push({
          server,
          model,
          key: `${server.id}:${model}`
        });
      }
    }

    await Promise.all(jobs.map(job => this.runJob(job)));
  }

  /* ----------------------------------------------------------
     Core worker
     ---------------------------------------------------------- */
  /** Perform the actual benchmark HTTP call */
  private async benchmarkServerModel(server: AIServer, model: string): Promise<void> {
    const url = `${server.url}/${model}`;
    const controller = new AbortController();
    const timeout = setTimeout(() => controller.abort(), BenchmarkModule.TIMEOUT);

    try {
      const resp = await fetch(url, { signal: controller.signal });
      if (!resp.ok) throw new Error(`HTTP ${resp.status}`);
      const data = await resp.json();
      this.setBenchmark(`${server.id}:${model}`, data);
    } finally {
      clearTimeout(timeout);
    }
  }
}
