## 2. Standardised response helpers (src/shared/response.ts)

```ts
// src/shared/response.ts
import { Response } from 'express';

export type StandardResponse<T = unknown> = {
  status: string;
  data?: T;
  error?: string;
};

/**
 * Send a JSON response with a consistent shape.
 */
export function sendSuccess<T>(res: Response, data: T, statusCode = 200) {
  res.status(statusCode).json({ status: 'success', data } as StandardResponse<T>);
}

/**
 * Send a JSON error response.
 */
export function sendError<T extends Error>(
  res: Response,
  error: T,
  statusCode = 500,
  code = 'internal_server_error',
) {
  res.status(statusCode).json({
    status: 'error',
    error: error.message,
    code,
  } as StandardResponse<null>);
}
```

