// src/shared/ndjson.ts
import { Response } from 'express';

/**
 * Write a JSON line (NDJSON) to the response stream.
 */
export function writeNDJSON(res: Response, payload: unknown) {
  res.write(JSON.stringify(payload) + '\n');
}
