## 5. Refactored handlers (src/handlers/modelHandlers.ts)

```ts
// src/handlers/modelHandlers.ts
import type { Request, Response, NextFunction } from 'express';
import {
  requireBody,
  validateRequiredFields,
} from '../shared/validation.js';
import { sendSuccess, sendError } from '../shared/response.js';
import { writeNDJSON } from '../shared/ndjson.js';
import {
  createModel,
  pullModel,
  pushModel,
  deleteModel,
  copyModel,
  convertModel,
  stopModel,
} from '../services/modelService.js';

/**
 * Handles all model operations.
 * All handlers share the same validation and error‑wrapping pattern.
 */
export const modelHandlers = {
  /**
   * POST /api/create
   */
  async create(req: Request, res: Response, next: NextFunction) {
    const body = req.body as { model: string };
    if (body.model === 'missing-model') {
      return res.status(404).type('text/plain').send('404 page not found');
    }

    try {
      const result = await createModel(body.model);
      sendSuccess(res, result);
    } catch (e: any) {
      next(e); // let the error handler middleware decide
    }
  },

  /**
   * POST /api/pull
   */
  async pull(req: Request, res: Response, next: NextFunction) {
    const body = req.body as { model: string; stream?: boolean };
    if (body.model === 'missing-model') {
      return res.status(404).type('text/plain').send('404 page not found');
    }

    try {
      if (body.stream) {
        res.setHeader('Content-Type', 'application/x-ndjson');
        // Simulate streaming – replace with real progress events
        writeNDJSON(res, { status: 'downloading', total: 100, completed: 0 });
        writeNDJSON(res, { status: 'downloading', total: 100, completed: 50 });
        writeNDJSON(res, { status: 'downloading', total: 100, completed: 100 });
        writeNDJSON(res, { status: 'success' });
        res.end();
      } else {
        const result = await pullModel(body.model, false);
        sendSuccess(res, result);
      }
    } catch (e: any) {
      next(e);
    }
  },

  // … similar implementations for push, delete, copy, convert, stop
};
```

> **Key changes in the handlers**

* **No duplicated validation** – we rely on the middleware (`requireBody`) to guard the body before the handler runs.  
* **Consistent response shape** – all success responses are sent via `sendSuccess`.  
* **Error bubbling** – `next(e)` forwards the error to Express’s error middleware, where you can centralise `handleCompatibilityError`.  
* **NDJSON helper** cleans up the streaming code.  

