import { requireBody } from '../shared/validation.js';
import { modelHandlers } from '../handlers/modelHandlers.js';

const router = Router();

router.post('/create', requireBody(['model'])(modelHandlers.create));
router.post('/pull', requireBody(['model'])(modelHandlers.pull));
// … repeat for the rest

export default router;
