## 7. Error handling middleware (src/middleware/errorHandler.ts)

```ts
// src/middleware/errorHandler.ts
import { Request, Response, NextFunction } from 'express';
import { handleCompatibilityError } from '../shared/index.js';

/**
 * Centralised async error wrapper
 */
export function asyncWrapper(
  fn: (req: Request, res: Response, next: NextFunction) => Promise<any>,
) {
  return (req: Request, res: Response, next: NextFunction) =>
    fn(req, res, next).catch(next);
}

/**
 * Express error‑handling middleware
 */
export function expressErrorHandler(
  err: Error,
  req: Request,
  res: Response,
  next: NextFunction,
) {
  // Convert the error to the legacy shape you already have
  handleCompatibilityError(err, res);
  // or, if you prefer the new JSON contract:
  // sendError(res, err);
}
```

Add it to your main app:

```ts
import { expressErrorHandler } from './middleware/errorHandler.js';
app.use('/api/models', modelRoutes);
app.use(expressErrorHandler); // this must come *after* all routes
```

