### Refactored skeleton

```ts
import type { Request, Response, NextFunction } from 'express';
import type { AIServer } from '../../orchestrator.js';
import { handleCompatibilityError, sendErrorResponse } from '../shared/index.js';
import { setupStreamingHeaders } from '../shared/index.js';
import { validateRequiredFields } from '../shared/index.js';
import { getOrchestrator } from '../shared/index.js';
import logger from '../utils/logger.js';

interface PullRequestBody {
  name: string;
  insecure?: boolean;
  stream?: boolean;
}

export const validatePullBody = (
  req: Request,
  res: Response,
  next: NextFunction,
): void => {
  const validation = validateRequiredFields(req.body, ['name']);
  if (!validation.isValid) {
    return sendErrorResponse(
      res,
      400,
      `Missing required fields: ${validation.missing.join(', ')}`,
      'invalid_request_error',
    );
  }
  next();
};

const chooseHealthyServer = (orchestrator: AIServerOrchestrator): AIServer | undefined =>
  orchestrator.getServers().find((s) => s.healthy);

class PullError extends Error {
  constructor(public status: number, message: string) {
    super(message);
  }
}

async function fetchPull(server: AIServer, body: PullRequestBody): Promise<Response> {
  const resp = await fetch(`${server.url}/api/pull`, {
    method: 'POST',
    headers: { 'Content-Type': 'application/json' },
    body: JSON.stringify(body),
  });

  if (!resp.ok) {
    const errMsg = await resp.text();
    throw new PullError(resp.status, errMsg);
  }

  return resp;
}

/**
 * POST /api/pull
 * Pull a model from a registry (streaming NDJSON response).
 */
export async function pullHandler(req: Request, res: Response, next: NextFunction): Promise<void> {
  try {
    const body = req.body as PullRequestBody;
    const { name, insecure = false, stream = true } = body;

    const orchestrator = await getOrchestrator(req);
    const server = chooseHealthyServer(orchestrator);

    if (!server) {
      return sendErrorResponse(
        res,
        503,
        'No healthy servers available for model pull',
        'service_unavailable',
      );
    }

    const resp = await fetchPull(server, { name, insecure, stream });

    if (stream) {
      setupStreamingHeaders(res, { contentType: 'application/x-ndjson' });
      for await (const chunk of resp.body as NodeJS.ReadableStream) {
        res.write(chunk as Buffer);
      }
      res.end();
    } else {
      const result = await resp.json();
      res.status(200).json(result);
    }

    // Invalidate cache after successful pull
    await orchestrator.updateAllStatusAndCache();
  } catch (error) {
    logger.error(`[ollama-pull] Error:`, error);

    if (error instanceof PullError) {
      const { status, message } = error;
      const type = status === 404 ? 'model_not_found' : 'pull_error';
      return sendErrorResponse(res, status, message, type);
    }

    // Compatibility path for older errors
    handleCompatibilityError(res, error, 'Failed to pull model');
  }
}
```

