/**
 * OpenAI Compatibility: `/v1/assistants` endpoint
 *
 * This module implements a minimal, in‑memory mock of the OpenAI Assistants API
 * (`/v1/assistants`).  It is useful for local development or unit testing
 * where a full OpenAI backend is not required.
 *
 * Endpoints implemented
 * ----------------------
 *  • GET    /v1/assistants          → `openaiListAssistantsHandler`
 *  • POST   /v1/assistants          → `openaiCreateAssistantHandler`
 *  • GET    /v1/assistants/:id      → `openaiRetrieveAssistantHandler`
 *  • DELETE /v1/assistants/:id      → `openaiDeleteAssistantHandler`
 *
 * Note: This implementation stores all assistants in a `Map` that lives in
 * process memory.  Restarting the process will lose all data.  In a real
 * deployment you should persist the data to a database.
 */

import { Request, Response, RequestHandler } from 'express';
import { v4 as uuidv4 } from 'uuid';
import { logger } from '../../../../shared/logging/logger.js';

/**
 * Internal representation of an Assistant.
 *
 * @property {string} id           – Unique identifier (prefixed with `asst_`).
 * @property {'assistant'} object  – Type marker (always `"assistant"`).
 * @property {number} created_at  – Unix timestamp (seconds) when the assistant was created.
 * @property {string|null} name
 * @property {string|null} description
 * @property {string} model      – The LLM model to use.
 * @property {string|null} instructions
 * @property {any[]} tools      – List of tool descriptors (e.g. code_interpreter, retrieval, function).
 * @property {string[]} file_ids – IDs of files attached to the assistant.
 * @property {Record<string, any>} metadata  – User‑supplied key/value pairs.
 */
interface AssistantRecord {
    id: string;
    object: 'assistant';
    created_at: number;
    name: string | null;
    description: string | null;
    model: string;
    instructions: string | null;
    tools: any[];
    file_ids: string[];
    metadata: Record<string, any>;
}

/**
 * In‑memory store of assistants.
 *
 * @type {Map<string, AssistantRecord>}
 * @example
 *   assistants.set('asst_123', { … })
 */
const assistants = new Map<string, AssistantRecord>();

/**
 * GET /v1/assistants
 *
 * @summary Lists assistants with optional pagination and ordering.
 * @param {Request} req - Express request object; expects `limit`, `order`, `after`, `before` query parameters.
 * @param {Response} res - Express response object.
 * @returns {Promise<void>} Sends a JSON response containing a list of assistants.
 * @throws {Error} Logs and returns a 500 response on internal errors.
 */
export const openaiListAssistantsHandler: RequestHandler = async (req, res): Promise<void> => {
    try {
        const { limit = 20, order = 'desc', after, before } = req.query;

        let assistantsList = Array.from(assistants.values());

        // Sort by creation timestamp
        assistantsList.sort((a, b) =>
            order === 'desc' ? b.created_at - a.created_at : a.created_at - b.created_at
        );

        // Pagination – `after` returns records following the given ID
        if (after) {
            const afterIndex = assistantsList.findIndex(a => a.id === after);
            if (afterIndex >= 0) assistantsList = assistantsList.slice(afterIndex + 1);
        }

        // Pagination – `before` returns records preceding the given ID
        if (before) {
            const beforeIndex = assistantsList.findIndex(a => a.id === before);
            if (beforeIndex >= 0) assistantsList = assistantsList.slice(0, beforeIndex);
        }

        const limitNum = parseInt(limit as string, 10);
        if (limitNum > 0) assistantsList = assistantsList.slice(0, limitNum);

        res.json({
            object: 'list',
            data: assistantsList,
            first_id: assistantsList.length > 0 ? assistantsList[0].id : null,
            last_id: assistantsList.length > 0 ? assistantsList[assistantsList.length - 1].id : null,
            has_more: false, // Not implementing full cursor logic
        });
    } catch (error) {
        logger.error(`Error listing assistants: ${error}`);
        res.status(500).json({
            error: {
                message: 'Internal server error',
                type: 'server_error',
                code: 'internal_error',
            },
        });
    }
};

/**
 * POST /v1/assistants
 *
 * @summary Creates a new assistant.
 * @param {Request} req - Express request object; expects a JSON body matching the OpenAI schema.
 * @param {Response} res - Express response object.
 * @returns {Promise<void>} Returns the created assistant in JSON format.
 * @throws {400} If required fields are missing or contain invalid values.
 * @throws {500} Internal server error – logged and returned as a generic error.
 */
export const openaiCreateAssistantHandler: RequestHandler = async (req, res): Promise<void> => {
    try {
        const {
            model,
            name = null,
            description = null,
            instructions = null,
            tools = [],
            file_ids = [],
            metadata = {},
        } = req.body;

        if (!model) {
            return res.status(400).json({
                error: {
                    message: 'Model is required',
                    type: 'invalid_request_error',
                    code: 'missing_model',
                },
            });
        }

        // Validate tools
        const validToolTypes = ['code_interpreter', 'retrieval', 'function'];
        for (const tool of tools) {
            if (!tool.type || !validToolTypes.includes(tool.type)) {
                return res.status(400).json({
                    error: {
                        message: `Invalid tool type. Must be one of: ${validToolTypes.join(', ')}`,
                        type: 'invalid_request_error',
                        code: 'invalid_tool_type',
                    },
                });
            }
            if (tool.type === 'function' && !tool.function) {
                return res.status(400).json({
                    error: {
                        message: 'Function tool requires function definition',
                        type: 'invalid_request_error',
                        code: 'missing_function',
                    },
                });
            }
        }

        const assistantId = 'asst_' + uuidv4().replace(/-/g, '');
        const created_at = Math.floor(Date.now() / 1000);

        const assistant: AssistantRecord = {
            id: assistantId,
            object: 'assistant',
            created_at,
            name,
            description,
            model,
            instructions,
            tools,
            file_ids,
            metadata,
        };

        assistants.set(assistantId, assistant);

        res.json(assistant);
    } catch (error) {
        logger.error(`Error creating assistant: ${error}`);
        res.status(500).json({
            error: {
                message: 'Internal server error',
                type: 'server_error',
                code: 'internal_error',
            },
        });
    }
};

/**
 * GET /v1/assistants/:assistant_id
 *
 * @summary Retrieves a single assistant by ID.
 * @param {Request} req - Express request object; expects `assistant_id` param.
 * @param {Response} res - Express response object.
 * @returns {Promise<void>} Returns the requested assistant in JSON.
 * @throws {400} If the ID is missing.
 * @throws {404} If the assistant does not exist.
 * @throws {500} Internal server error.
 */
export const openaiRetrieveAssistantHandler: RequestHandler = async (req, res): Promise<void> => {
    try {
        const { assistant_id } = req.params;

        if (!assistant_id) {
            return res.status(400).json({
                error: {
                    message: 'Assistant ID is required',
                    type: 'invalid_request_error',
                    code: 'missing_assistant_id',
                },
            });
        }

        const assistant = assistants.get(assistant_id);

        if (!assistant) {
            return res.status(404).json({
                error: {
                    message: 'Assistant not found',
                    type: 'invalid_request_error',
                    code: 'assistant_not_found',
                },
            });
        }

        res.json(assistant);
    } catch (error) {
        logger.error(`Error retrieving assistant: ${error}`);
        res.status(500).json({
            error: {
                message: 'Internal server error',
                type: 'server_error',
                code: 'internal_error',
            },
        });
    }
};

/**
 * DELETE /v1/assistants/:assistant_id
 *
 * @summary Deletes an assistant.
 * @param {Request} req - Express request object; expects `assistant_id` param.
 * @param {Response} res - Express response object.
 * @returns {Promise<void>} Returns a deletion confirmation object.
 * @throws {400} If the ID is missing.
 * @throws {404} If the assistant does not exist.
 * @throws {500} Internal server error.
 */
export const openaiDeleteAssistantHandler: RequestHandler = async (req, res): Promise<void> => {
    try {
        const { assistant_id } = req.params;

        if (!assistant_id) {
            return res.status(400).json({
                error: {
                    message: 'Assistant ID is required',
                    type: 'invalid_request_error',
                    code: 'missing_assistant_id',
                },
            });
        }

        const assistant = assistants.get(assistant_id);

        if (!assistant) {
            return res.status(404).json({
                error: {
                    message: 'Assistant not found',
                    type: 'invalid_request_error',
                    code: 'assistant_not_found',
                },
            });
        }

        assistants.delete(assistant_id);

        res.json({
            object: 'assistant',
            deleted: true,
            id: assistant_id,
        });
    } catch (error) {
        logger.error(`Error deleting assistant: ${error}`);
        res.status(500).json({
            error: {
                message: 'Internal server error',
                type: 'server_error',
                code: 'internal_error',
            },
        });
    }
};
