import { Request, Response, RequestHandler } from 'express';
import { v4 as uuidv4 } from 'uuid';

jest.mock('uuid', () => ({
  v4: jest.fn(() => '1234-5678-90ab-cdef')
}));

// Helper to create mock req/res objects
function mockReqRes(
  body: any = {},
  query: any = {},
  params: any = {}
): { req: Request; res: Response } {
  const req = {
    body,
    query,
    params
  } as unknown as Request;
  const res = {
    status: jest.fn().mockReturnThis(),
    json: jest.fn()
  } as unknown as Response;
  return { req, res };
}

describe('OpenAI Assistant Handlers', () => {
  let openaiCreateAssistantHandler: RequestHandler;
  let openaiRetrieveAssistantHandler: RequestHandler;
  let openaiDeleteAssistantHandler: RequestHandler;
  let openaiListAssistantsHandler: RequestHandler;

  beforeEach(async () => {
    jest.resetModules(); // Reset module cache so the in‑memory map is fresh
    const mod = await import('./openaiAssistants.js');
    openaiCreateAssistantHandler = mod.openaiCreateAssistantHandler;
    openaiRetrieveAssistantHandler = mod.openaiRetrieveAssistantHandler;
    openaiDeleteAssistantHandler = mod.openaiDeleteAssistantHandler;
    openaiListAssistantsHandler = mod.openaiListAssistantsHandler;
  });

  // ---------- CREATE ----------
  test('create assistant – success', async () => {
    const { req, res } = mockReqRes({
      model: 'gpt-4',
      name: 'Test',
      tools: [{ type: 'retrieval' }]
    });

    await openaiCreateAssistantHandler(req, res);

    expect(res.json).toHaveBeenCalledTimes(1);
    const payload = res.json.mock.calls[0][0];
    expect(payload).toMatchObject({
      id: 'asst_1234567890abcdef',
      model: 'gpt-4',
      name: 'Test',
      tools: [{ type: 'retrieval' }]
    });
  });

  test('create assistant – missing model', async () => {
    const { req, res } = mockReqRes({ name: 'NoModel' });

    await openaiCreateAssistantHandler(req, res);

    expect(res.status).toHaveBeenCalledWith(400);
    const err = res.json.mock.calls[0][0];
    expect(err.error).toMatchObject({
      code: 'missing_model',
      type: 'invalid_request_error'
    });
  });

  test('create assistant – invalid tool type', async () => {
    const { req, res } = mockReqRes({
      model: 'gpt-4',
      tools: [{ type: 'invalid' }]
